((window.LMT_BODY = window.LMT_BODY || {})["namemap"] = window.LMT_BODY["namemap"] || {})["hi"] = {"john-ivan-sean-yahya":"<p>हिब्रू नाम <strong>Yōḥānān</strong> (יוֹחָנָן) में <em>Yô-</em>, यानी ईश्वर के नाम का एक संक्षिप्त रूप, क्रिया <em>ḥānan</em> (अनुग्रह करना) से जुड़ता है; हिब्रू बाइबिल में इसका लंबा रूप Yəhôḥānān (Jehohanan) भी मिलता है। मानचित्र पर John की प्रविष्टि 43 में से 32 ख़ाने भरती है, और लगभग हर रूप सुसमाचारों की दो वर्तनियों में से किसी एक तक पहुँचता है: यूनानी <strong>Iōánnēs</strong> (Ἰωάννης) और लैटिन <strong>Iohannes</strong>।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setname\" data-name=\"john\">👤 मानचित्र पर जॉन दिखाएँ</button><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"49\" data-lng=\"18\" data-zoom=\"4\">🌍 वहाँ चलें जहाँ यान और इवान मिलते हैं</button></div><h3>यूनानी ने ḥ गिरा दिया</h3><p>यूनानी में ग्रसनीय <em>ḥ</em> था ही नहीं, इसलिए Iōánnēs में यह नहीं है, और इसे पुल्लिंग प्रत्यय <em>-ēs</em> मिला ताकि इसके रूप यूनानी संज्ञा की तरह चल सकें। लैटिन Iohannes में स्वरों के बीच <em>h</em> लिखा जाता है। आधुनिक यूनानी पुरानी वर्तनी Ιωάννης बनाए रखती है, पर उच्चारण <em>Ioánnis</em> /i.oˈa.nis/ है, क्योंकि <em>ē</em> अब <em>i</em> हो चुका है; रोज़मर्रा का रूप Giannis है, जैसे Giannis Antetokounmpo (यानिस अंतेतोकुम्पो) में। जॉर्जियाई <em>Ioane</em> और रोमानियाई <em>Ioan</em> चर्च वाले रूप के क़रीब रहते हैं; रोमानिया में बोलचाल का रूप Ion है, जैसे लेखक Ion Creangă (इओन क्रयांगा) में।</p><h3>एक लैटिन अक्षर, तीन रोमांस ध्वनियाँ</h3><p>लैटिन में स्वर से पहले आनेवाला <em>I</em> व्यंजन /j/ था। रोमांस-भाषी क्षेत्र के अधिकांश हिस्से में यह कठोर होकर /dʒ/ बन गया: लैटिन <em>iocus</em> (हँसी-मज़ाक़) से इतालवी <em>gioco</em>, फ़्रांसीसी <em>jeu</em> और स्पेनी <em>juego</em> बने। इतालवी ने /dʒ/ बनाए रखा और उसे <em>gi-</em> लिखती है: <strong>Giovanni</strong> /dʒoˈvanni/, जिसमें <em>o</em> और <em>a</em> के बीच की ख़ाली जगह एक <em>v</em> ने भर दी। पुरानी फ़्रांसीसी का <em>Jehan</em> भी /dʒ/ से शुरू होता था; 13वीं सदी में फ़्रांसीसी ने /dʒ/ को घटाकर /ʒ/ कर दिया, और इसी से <strong>Jean</strong> /ʒɑ̃/ बना। पुर्तगाली में भी यही /ʒ/ है, और उसने अंतिम <em>-an</em> को अनुनासिक संयुक्त स्वर में बदल दिया: <strong>João</strong> /ʒwɐ̃w/। पुरानी स्पेनी भी Juan के <em>j</em> को /ʒ/ ही बोलती थी, पर 16वीं और 17वीं सदी के आरंभ में स्पेनी ने इसे अघोष करके /ʃ/ बनाया और फिर पीछे खिसकाकर कंठ्य /x/ कर दिया, इसलिए <strong>Juan</strong> अब /xwan/ है। स्पेनी यह नाम फ़िलीपींस ले गई, जहाँ फ़िलिपीनो Juan /hwan/ आम आदमी का प्रतीक है, Juan dela Cruz के रूप में।</p><h3>John और Seán: नॉर्मन आयात</h3><p>अंग्रेज़ी ने यह नाम नॉर्मन फ़्रांसीसी से लिया, और तब लिया जब फ़्रांसीसी ने /dʒ/ का स्पर्श-अंश अभी खोया नहीं था। इसलिए <strong>John</strong> /dʒɒn/ में वही पुराना फ़्रांसीसी व्यंजन बचा है, जैसे <em>joy</em> और <em>judge</em> में; वर्तनी का <em>h</em> लैटिन <em>Johannes</em> से आया है। 1169 से आयरलैंड पहुँचे एंग्लो-नॉर्मन अपने साथ <em>Jehan</em> लाए। आयरिश में शब्द के आरंभ में न /dʒ/ था न /ʒ/, इसलिए उसकी जगह तालव्य (slender) <em>s</em>, यानी /ʃ/, का प्रयोग हुआ: पुराना रूप <em>Seaghán</em>, आज <strong>Seán</strong> /ʃaːn/। <em>Irish Names and Surnames</em> (1923) में पैट्रिक वुल्फ़ (Patrick Woulfe) इसे \"आरंभिक एंग्लो-नॉर्मन बसनेवालों में सबसे आम नामों में से एक\" कहते हैं और इसे <em>Eoin</em> का एक रूपांतर बताते हैं, जो लैटिन से लिया गया पुराना आयरिश रूप है।</p><h3>जहाँ लैटिन j, j ही रहा</h3><p>जर्मन, स्कैंडिनेवियाई, डच, पश्चिमी स्लाव, हंगेरियन और फ़िनिश बोलनेवाले लैटिन <em>J</em> को /j/ पढ़ते थे, इसलिए यह व्यंजन कभी नहीं बदला, और रूपों में फ़र्क़ बस इतना है कि शब्द का कितना हिस्सा बचा। जर्मन में <strong>Johannes</strong> /joˈhanəs/ है, जो छोटा होकर Johann (Johann Sebastian Bach, योहान सेबास्टियन बाख़) बनता है और पहला शब्दांश गिर जाने पर Hans। स्वीडिश और नॉर्वेजियन में <em>Johan</em>, फ़िनिश में <em>Juhani</em>, और हंगेरियन में <em>János</em> है, जो लैटिन <em>-s</em> को बचाए हुए है। डच, पोलिश और चेक इसे एक ही शब्दांश तक घटाकर <strong>Jan</strong> कर देते हैं: Jan Steen, Jan Hus, Jan III Sobieski। और दूर के मिशनरी रूप भी यही ढर्रा अपनाते हैं: इंडोनेशियाई <em>Yohanes</em>, कोरियाई 요한 <em>Yohan</em>, और वियतनामी कैथोलिक <em>Gioan</em>, जो <em>Gi-</em> से लिखा जाता है और हनोई में /z/ तथा दक्षिण में /j/ से बोला जाता है।</p><h3>इवान: यूनानी धारा</h3><p>कुस्तुंतुनिया के प्रभाव में ईसाई बने स्लावों को यह नाम यूनानी से चर्च स्लावोनिक के रास्ते मिला, जिसमें इसे Иоаннъ (<em>Ioannŭ</em>) लिखा जाता था। बोलचाल में यह <strong>Ivan</strong> बन गया: <em>i</em> और <em>a</em> के बीच का <em>o</em> <em>v</em> में बदल गया, जबकि इतालवी Giovanni ने <em>o</em> रखा और उसके बाद एक <em>v</em> जोड़ दिया। रूसी Иван /ɪˈvan/ और यूक्रेनी Іван /iˈʋɑn/ यही दिखाते हैं। क्रोएशियाई में भी Ivan है, हालाँकि क्रोएशिया कैथोलिक है और उत्तर में उसके कैथोलिक पड़ोसी, पोलैंड और चेकिया, Jan कहते हैं। यानी दोनों रूपों की सीमा-रेखा ठीक-ठीक चर्च-निष्ठा के हिसाब से नहीं चलती।</p><h3>वे रूप जिनमें गले की ध्वनि बची है</h3><p>यूनान के पूर्व में कई रूप वह बीच का व्यंजन बचाए हुए हैं जिसे यूनानी ने खो दिया। अरबी-भाषी ईसाई, जिनमें मिस्र के कॉप्ट भी शामिल हैं (मानचित्र का अरबी ख़ाना), <strong>Yūḥannā</strong> (يوحنا) कहते हैं, <em>ḥ</em> के साथ, ठीक सिरियाई <em>Yuḥanan</em> की तरह। अम्हारी <strong>ዮሐንስ</strong> <em>Yoḥannis</em>, जो सम्राट योहानेस चतुर्थ (Yohannes IV) का नाम था, गे'एज़ अक्षर ሐ <em>ḥa</em> से लिखा जाता है। आर्मेनियाई <strong>Hovhannes</strong> के बीच में एक <em>h</em> है, और उसका पहला <em>H</em> शास्त्रीय वर्तनी Յովհաննէս से आता है, जिसका अक्षर յ शब्द के आरंभ में <em>h</em> बोला जाता है। आधुनिक हिब्रू मूल יוֹחָנָן का उच्चारण <em>Yoḥanan</em> /joχaˈnan/ करती है।</p><h3>याह्या</h3><p>क़ुरआन यूहन्ना बपतिस्मा देनेवाले को पाँच बार <strong>Yaḥyā</strong> (يحيى) कहता है (3:39, 6:85, 19:7, 19:12, 21:90), और 19:7 में कहा गया है कि यह नाम उनसे पहले किसी को नहीं दिया गया था। Yaḥyā का Yōḥānān से क्या संबंध है, इस पर मतभेद है। मुस्लिम परंपरा इसे धातु <em>ḥ-y-y</em> से बना अरबी क्रिया-रूप मानती है, जिसका अर्थ है वह जीवित रहता है। इसके उलट कुछ पश्चिमी विद्वानों का प्रस्ताव है कि यह बिना बिंदुओं के लिखे Yuḥannā जैसे किसी रूप को ग़लत पढ़ने से बना। उत्तर-पश्चिमी अरब के अल-उला से मिला एक क़ब्र-अभिलेख, जो स्थानीय संवत् के वर्ष 201 (ई. 306/307) का है, शमौन के पुत्र किसी <em>Yḥyʾ</em> ने अपने पिता शमौन के लिए लगवाया था; यह रॉबर्ट हॉयलैंड (Robert Hoyland) के हिजाज़ के यहूदी अभिलेखों पर 2011 के अध्ययन में दर्ज है। यानी यह नाम क़ुरआन से तीन सदी पहले एक यहूदी परिवार में प्रचलित था। मानचित्र पर फ़ारसी ख़ाने में Yahyā (یحیی) है। इंडोनेशिया में ईसाई रूप Yohanes है और मुस्लिम रूप Yahya।</p>","james-jacob-santiago":"<h3>एड़ी या प्रार्थना</h3><p>हिब्रू नाम है <strong>Yaʿaqov</strong> (יַעֲקֹב)। उत्पत्ति 25:26 इसे एक शब्द-क्रीड़ा से समझाती है: जुड़वाँ भाइयों में दूसरा अपने भाई एसाव की एड़ी, <em>ʿaqev</em>, पकड़े हुए पैदा हुआ था। लेकिन टीकाकार आमतौर पर इसे <em>Yaʿqub-ʾel</em> जैसे किसी लंबे नाम का छोटा रूप मानते हैं, जिसका अर्थ है “एल रक्षा करें”। गॉर्डन वेनहम ने 1994 में उत्पत्ति पर लिखी अपनी टीका में इसे ईसा पूर्व दूसरी सहस्राब्दी के आरंभ का एक विशिष्ट एमोराइट नाम कहा है और सीरिया के चगर बाज़ार से लगभग 1800 ईसा पूर्व के उदाहरण दिए हैं। इस पुनर्रचना में भी क्रिया का अर्थ अनिश्चित ही रहता है।</p><h3>कुलपिता के लिए Jacob, प्रेरितों के लिए James</h3><p>यूनानी अनुवादकों ने इस नाम को दो तरह से बरता। सेप्टुआजिंट और नए नियम में कुलपिता <em>Iakōb</em> (Ἰακώβ) ही रहते हैं, एक ऐसा रूप जिसका अंत कभी नहीं बदलता। याकूब नाम के दोनों प्रेरितों और याकूब के पत्र के लेखक को <em>Iakōbos</em> (Ἰάκωβος) मिलता है, जो यूनानी कारक-प्रत्यय लेता है। जेरोम की लैटिन वल्गेट भी यही विभाजन बनाए रखती है: <em>Iacob</em> और <em>Iacobus</em>। अंग्रेज़ी बाइबलों ने इन्हें दो अलग नाम बना दिया, Jacob और James, और इसीलिए अंग्रेज़ी में इस पत्र को Epistle of James कहते हैं। कोरियाई प्रोटेस्टेंट बाइबलें भी दो रूप इस्तेमाल करती हैं, 야곱 <em>Yagop</em> और 야고보 <em>Yagobo</em>। जापानी में दोनों के लिए ヤコブ है, और चीनी में दोनों के लिए 雅各।</p><h3>Iacomus और Iacobus</h3><p>बोलचाल की लैटिन में एक रूपांतर बना, <strong>Iacomus</strong>, जिसमें <em>b</em> की जगह <em>m</em> है। इसी से पुरानी फ़्रांसीसी का <em>James</em> बना, जिसे अंग्रेज़ी ने उधार लिया। इसी से इतालवी <strong>Giacomo</strong> (मानचित्र पर जाकोमो पुच्चीनी), कातालान <em>Jaume</em>, और स्पेनी व पुर्तगाली <em>Jaime</em> भी निकले। बिना बदले <em>Iacobus</em> से फ़्रांसीसी <strong>Jacques</strong>, जर्मन, डच और स्वीडिश <strong>Jakob</strong>, पोलिश और चेक <strong>Jakub</strong>, और हंगेरियाई <strong>Jakab</strong> बने। रूसी <strong>Яков</strong> और यूक्रेनी <strong>Яків</strong> सीधे यूनानी से चर्च स्लावोनिक के रास्ते आए। अंग्रेज़ी ने व्युत्पन्न शब्दों में लैटिन का <em>b</em> बचाए रखा। <em>Jacobean</em> काल जेम्स प्रथम का शासनकाल (1603–1625) है, और <em>Jacobites</em> वे लोग थे जिन्होंने 1688 के बाद निर्वासित जेम्स द्वितीय और उनके उत्तराधिकारियों का समर्थन किया।</p><h3>Sant Iago</h3><p>मध्यकालीन स्पेनी में <em>Iacobus</em> घिसकर <em>Iago</em> या <em>Yago</em> रह गया, और इस तरह ज़ेबेदी के पुत्र प्रेरित याकूब <em>Sant Iago</em>, यानी “संत याकूब”, बन गए। कोम्पोस्तेला की किंवदंती के अनुसार लगभग 814 में पेलेगियस नाम के एक संन्यासी को गालीसिया में उनकी क़ब्र मिली। फिर इरिया फ़्लाविया के बिशप थियोडेमिर ने अस्तूरियस के राजा अल्फ़ोंसो द्वितीय (शासन 791–842) को इसकी सूचना दी। वहाँ बसे शहर तक जाने वाले तीर्थ-मार्ग कामिनो दे सांतियागो कहलाते हैं। संत की उपाधि घुलकर एक ही व्यक्तिगत नाम बन गई, <strong>Santiago</strong>। स्पेन, मेक्सिको और फ़िलीपींस के खानों में यही रूप है, और स्पेन के खाने में सांतियागो रामोन इ काहाल का नाम है। पुर्तगाली ने शब्द को दूसरी जगह से तोड़ा, उसे <em>São Tiago</em> पढ़ा, और <strong>Tiago</strong> को नाम के रूप में अपनाया। ब्राज़ील का <strong>Thiago</strong>, जैसे फ़ुटबॉलर थियागो सिल्वा के नाम में, वह <em>th</em> बचाए हुए है जिसे पुर्तगाल के 1911 के वर्तनी सुधार ने सामान्य शब्दों से हटा दिया था। वेल्श <em>Iago</em> भी यही नाम है, और शेक्सपियर ने इसे <em>ओथेलो</em> के खलनायक को दिया।</p><h3>दिएगो, विवादित सदस्य</h3><p>रॉबर्ट साउदी ने 1808 की अपनी <em>Chronicle of the Cid</em> में <strong>Diego</strong> को Tiago, यानी छोटे किए गए Santiago, का एक रूप माना। 1891 में अस्तूरियाई कोशकार अपोलिनार रातो इ एविया ने Diego को Yago, Tiago और Jacobo के साथ Santiago के रूपों में गिनाया। मध्यकालीन अभिलेख किसी और दिशा की ओर इशारा करते हैं। लैटिन <em>Didacus</em> इबेरियाई दस्तावेज़ों में 747 से मिलता है; आंतोनियो फ़्लोरियानो ने 1949 में इसके सबसे पुराने अभिलेख के लिए यही तिथि दी थी। 10वीं सदी में इसे <em>Diaco</em> और <em>Diago</em> लिखा जाता है। स्वयं <em>Diego</em> पहली बार 11वीं सदी के अंत में दिखता है और 14वीं सदी में मानक वर्तनी बन जाता है। जिन संत को स्पेनी में सान दिएगो दे अल्काला (मृत्यु 1463) कहा जाता है, वे लैटिन में <em>Didacus</em> हैं, और सेबास्तियान विस्काइनो ने 1602 में उन्हीं के नाम पर सैन डिएगो की खाड़ी का नाम रखा। याकोव मालकिएल 1975 में ही Diego को Santiago के बराबर मानने के ख़िलाफ़ तर्क दे चुके थे। दो प्रश्न अब भी खुले हैं। कोई नहीं जानता कि स्वयं Didacus कहाँ से आया; लिडिया बेकर ने 2009 में छठी से बारहवीं सदी तक के इबेरियाई व्यक्तिनामों के अपने सर्वेक्षण में <em>Diadochus</em> से यूनानी उत्पत्ति को, और बास्क व केल्टिक प्रस्तावों को भी, ख़ारिज किया है। बेकर यह भी बताती हैं कि <em>Diago</em> से <em>Diego</em> में हुए बदलाव की कोई सर्वमान्य व्याख्या नहीं है। उपनाम <em>Díaz</em> का अर्थ है “दिएगो का बेटा”।</p><h3>Yaʿqūb</h3><p>क़ुरआन में पैग़ंबर का नाम <strong>Yaʿqūb</strong> (يعقوب) है। यह शाखा यूनानी के रास्ते नहीं, सीधे सामी रूप से आती है। यह फ़ारसी और उर्दू یعقوب, तुर्की <strong>Yakup</strong>, इंडोनेशियाई <strong>Yakub</strong> और हाउसा <strong>Yakubu</strong> में आगे चलती है, जैसे याकूबू गोवॉन के नाम में, जो 1966 से 1975 तक नाइजीरिया के राष्ट्राध्यक्ष थे। चीनी मुसलमानों के प्रयोग में, जिसमें मा जियान का क़ुरआन अनुवाद भी शामिल है, यह नाम 叶尔孤白 <em>Yèʼěrgūbái</em> लिखा जाता है, और चीन के खाने में यही रूप है। यह नाम मानचित्र के 43 में से 31 खानों में आता है। दोनों अंग्रेज़ी-भाषी खानों में इस जोड़ी का एक-एक रूप है: संयुक्त राज्य अमेरिका के लिए <strong>Jacob</strong> और यूनाइटेड किंगडम के लिए <strong>James</strong>।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setname\" data-name=\"jacob\">👤 मानचित्र पर जैकब दिखाएँ</button><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"42.88\" data-lng=\"-8.54\" data-zoom=\"5\">🌍 सांतियागो दे कोम्पोस्तेला पर जाएँ</button></div>","mary-maryam-miriam":"<h3>एक नक्शे पर दो अंत</h3><p>नक्शे पर <strong>मैरी</strong> चुनिए, तो खाने अपनी आख़िरी ध्वनि के हिसाब से बँट जाते हैं। हिब्रू מִרְיָם <em>Miryam</em>, अरबी مريم और फ़ारसी مریم <em>Maryam</em>, उर्दू مریم <em>Maryam</em>, तुर्की <em>Meryem</em> और अम्हारी ማርያም <em>Maryam</em> के अंत में <em>-m</em> है, और स्वाहिली <em>Mariamu</em> <em>m</em> को बनाए रखकर अंत में <em>-u</em> जोड़ देती है। बाक़ी हर जगह नाम स्वर पर ख़त्म होता है: स्पेनिश <em>María</em>, इतालवी, जर्मन, पोलिश और पुर्तगाली <em>Maria</em>, यूनानी <em>Μαρία</em>, रूसी <em>Мария</em>, फ़्रांसीसी <em>Marie</em>, अंग्रेज़ी <em>Mary</em>।</p><p>यह बँटवारा यूनानी बाइबिल में ही मौजूद है। सेप्टुआजिंट, जिसका अनुवाद ईसा पूर्व तीसरी सदी में शुरू हुआ, मूसा की बहन का नाम Μαριαμ <em>Mariam</em> लिखता है (निर्गमन 15:20)। नया नियम यीशु की माँ के लिए <em>Mariam</em> और <em>Maria</em> दोनों का इस्तेमाल करता है। पहला रूप सामी नाम को ज्यों का त्यों ले आता है और उस पर कारक-प्रत्यय नहीं लगते। दूसरा <em>-a</em> पर ख़त्म होने वाली यूनानी स्त्रीलिंग संज्ञा है, इसलिए उस पर यूनानी कारक-प्रत्यय लग सकते थे। लैटिन ने <em>Maria</em> अपनाया, और लैटिन ईसाइयत की भाषाओं ने भी। <em>-m</em> वाला रूप आगे अरबी में पहुँचा। क़ुरआन की 19वीं सूरह का नाम <em>Maryam</em> है, और वे अकेली स्त्री हैं जिनका नाम क़ुरआन लेता है। अम्हारी खाना दिखाता है कि यह बँटवारा ईसाई बनाम मुसलमान का नहीं है: इथियोपियाई ऑर्थोडॉक्स चर्च में भी कुँवारी मरियम का नाम <em>Maryam</em> ही है।</p><p>स्वरों का भी अपना इतिहास है। हिब्रू <em>Miryam</em> का <em>i</em> मसोरेटिक स्वर-चिह्नों से आता है, जो ईसवी सन् की 7वीं से 10वीं सदी के बीच पाठ में जोड़े गए। यूनानी <em>Mariam</em> उससे कई सदियाँ पुराना है, और उसमें उस जगह <em>a</em> है।</p><h3>नाम का अर्थ क्या था</h3><p>कोई नहीं जानता। 1895 में ओटो बार्डेनह्यूवर ने <em>Der Name Maria</em> नाम का एक शोध-ग्रंथ प्रकाशित किया, जिसमें लगभग सत्तर सुझाए गए अर्थों पर चर्चा की गई थी। मुख्य अर्थ ये हैं:</p><ul><li><strong>मिस्री <em>mr</em> “प्रेम” या <em>mry</em> “प्रिय”</strong>, वही तत्व जो मेरितामुन, “आमुन की प्रिया”, जैसे नामों में मिलता है। Behind the Name मिस्री मूल को सबसे संभावित मानता है। 1912 के <em>कैथोलिक एनसाइक्लोपीडिया</em> में एंथनी मास का निष्कर्ष था कि “ऐसी व्युत्पत्ति केवल संभव है, या ज़्यादा से ज़्यादा मुश्किल से संभाव्य।”</li><li><strong>हिब्रू <em>mar</em> “कड़वा”</strong>, वही धातु जो <em>myrrh</em> (गंधरस) में है। पैट्रिक वुल्फ़ की <em>Irish Names and Surnames</em> (1923) इसी अर्थ को तरजीह देती है और कड़वाहट को शोक के अर्थ में पढ़ती है।</li><li><strong>हिब्रू <em>meri</em> “विद्रोह”</strong>, यह संबंध स्ट्रॉन्ग्स कॉन्कॉर्डेंस (1890) में दिया गया है।</li><li><strong>जेरोम का “समुद्र की बूँद”</strong>, लैटिन <em>stilla maris</em>, जो <em>mar</em> को “बूँद” और <em>yam</em> को “समुद्र” पढ़ता है। बाद की प्रतियों ने इसे बदलकर <em>stella maris</em>, “समुद्र का तारा”, कर दिया। 9वीं सदी के अंत की बैम्बर्ग की एक पांडुलिपि में अब भी <em>stilla</em> है। “समुद्र का तारा” कुँवारी मरियम की उपाधि बन गया, जैसे स्तोत्र <em>Ave maris stella</em> में।</li></ul><p>Behind the Name और बच्चों के नामों की किताबें “मनचाही संतान” अर्थ भी देती हैं, लेकिन उसकी कोई व्युत्पत्ति नहीं बतातीं।</p><h3>एक ही स्त्री के लिए रखा गया रूप</h3><p>आयरिश में इस नाम के दो रूप हैं। स्त्रियों का नाम <em>Máire</em> होता है। <em>Muire</em> का प्रयोग केवल कुँवारी मरियम के लिए होता है। अभिवादन <em>Dia dhuit</em>, “ईश्वर तुम्हें”, का जवाब <em>Dia is Muire dhuit</em>, “ईश्वर और मरियम तुम्हें”, से दिया जाता है। एकमात्र ज्ञात अपवाद गीत <em>Caoineadh na dTrí Mhuire</em> है, यानी क्रूस पर चढ़ाए जाने के समय तीन मरियमों का विलाप। वुल्फ़ को 17वीं सदी से पहले मैरी नाम की गिनी-चुनी आयरिश स्त्रियाँ ही मिलीं। पोलिश भी ऐसा ही भेद करती है: प्रार्थना में कुँवारी मरियम <em>Maryja</em> हैं, जबकि लड़की का नाम <em>Maria</em> रखा जाता है, और नक्शे पर यही रूप दिखाया गया है।</p><h3>पुरुषों के लिए मारिया, और कुँवारी मरियम की उपाधियाँ नामों के रूप में</h3><p>स्पेनिश दोहरे नाम में पहला हिस्सा लिंग तय करता है। <em>José María</em> पुरुष है, जैसे पूर्व प्रधानमंत्री होसे मारिया अज़नार। <em>María José</em> स्त्री है। María दूसरे पुरुष नामों के बाद भी आता है, जैसे Carlos María, Juan María और Luis María। स्पेन के बाहर भी पुरुष यह नाम रखते हैं: कार्ल मारिया फ़ॉन वेबर, राइनर मारिया रिल्के, ज़ाँ-मारी ल पेन।</p><p>कई स्पेनिश स्त्री-नाम कुँवारी मरियम की उपाधियाँ हैं, जिनमें से María हटा दिया गया है:</p><ul><li><strong>Dolores</strong> <em>Nuestra Señora de los Dolores</em>, यानी दुखों की माता, से आया है।</li><li><strong>Pilar</strong> सारागोसा की Virgen del Pilar (स्तंभ की कुँवारी) से आया है, जो परंपरा के अनुसार संत याकूब को एक स्तंभ पर दिखाई दी थीं।</li><li><strong>Rosario</strong> रोज़री (जपमाला) से आया है।</li><li><strong>Mercedes</strong> <em>María de las Mercedes</em>, यानी दयाओं की मरियम, से आया है।</li><li><strong>Carmen</strong> कार्मेल पर्वत की माता से आया है, जो हिब्रू <em>karmel</em> “बाग़, फलोद्यान” से है। बाद में इसकी वर्तनी लैटिन <em>carmen</em>, “गीत”, की ओर मोड़ दी गई।</li></ul><p>जनसंख्या गणना में आज भी लंबा रूप सबसे आगे है। 1 जनवरी 2024 को स्पेन के राष्ट्रीय सांख्यिकी संस्थान (INE) ने María Carmen नाम की 624,368 स्त्रियाँ गिनीं, जिससे यह स्पेन में स्त्रियों का सबसे आम नाम बना। María नाम की 551,105 और Carmen नाम की 340,920 स्त्रियाँ थीं।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setname\" data-name=\"mary\">👤 नक्शे पर मैरी दिखाएँ</button></div>","muhammad-mehmet-mamadou":"<p>अरबी नाम <strong>محمد</strong> <em>Muḥammad</em> क्रिया <em>ḥammada</em> “बहुत प्रशंसा करना” का कर्मवाच्य कृदंत है, और उसी धातु ḥ-m-d से बना है जिससे <em>Aḥmad</em> और <em>Maḥmūd</em> भी बने हैं; इसका अर्थ है “जिसकी प्रशंसा की गई हो”। नक्शे पर अरबी, सऊदी, फ़ारसी और उर्दू के खानों में एक ही चार अक्षर, محمد, लिखे हैं; फ़र्क़ सिर्फ़ रोमन लिप्यंतरण में है — अरबी <em>Muḥammad</em> बनाम फ़ारसी <em>Mohammad</em>। उर्दू में यह अक्सर उस नाम से पहले का पहला हिस्सा होता है जिससे व्यक्ति को पुकारा जाता है: पाकिस्तान के तीन बार प्रधानमंत्री रहे मुहम्मद नवाज़ शरीफ़ नवाज़ शरीफ़ के नाम से जाने जाते हैं। अरबी लिपि के बाहर इस नाम को हर भाषा की ध्वनियों के अनुसार नए सिरे से लिखा गया।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setname\" data-name=\"muhammad\">👤 नक्शे पर मुहम्मद दिखाएँ</button><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"39\" data-lng=\"35\" data-zoom=\"4\">🌍 तुर्की पर जाएँ</button></div><h3>Mehmet और Muhammed</h3><p>तुर्की खाने में <strong>Mehmet</strong> लिखा है। उस्मानी (ऑटोमन) तुर्की इस नाम को अरबी लिपि में वही محمد लिखती थी, और बोलने वाले इसे तुर्की <em>e</em> स्वरों के साथ <em>Mehemmed</em> पढ़ते थे, जो आगे चलकर छोटा होकर <em>Mehmed</em> हो गया। 1928 में अपनाई गई लैटिन वर्णमाला इसे उच्चारण के अनुसार, अंत में अघोष <em>t</em> के साथ लिखती है। छह उस्मानी सुल्तानों का नाम मेहमद था, जिनमें मेहमद द्वितीय भी थे, जिन्होंने 1453 में कुस्तुन्तुनिया जीता। 2025 में तुर्की के पता-आधारित जनसंख्या रजिस्टर में Mehmet नाम के 1,271,896 पुरुष दर्ज थे — किसी भी दूसरे नाम से ज़्यादा — जो Mustafa (1,057,634) और Ahmet (857,105) से आगे थे।</p><p>स्वयं पैग़ंबर तुर्की में <em>Hz. Muhammed</em> हैं, कभी Mehmet नहीं। कुछ पुरुष <em>Muhammed</em> या <em>Muhammet</em> नाम से दर्ज हैं, लेकिन इनमें से कोई भी 2025 के रजिस्टर में पुरुषों के दस सबसे आम नामों में नहीं है; यह सूची 434,992 के साथ İsmail पर ख़त्म होती है। तुर्की में आम तौर पर इसका कारण श्रद्धा बताया जाता है: आम लोगों को नाम का बदला हुआ रूप मिला, और हूबहू नाम पैग़ंबर के लिए रखा गया। यह एक पारंपरिक कथन है, नामकरण का कोई प्रलेखित नियम नहीं। उस्मानी लिपि दोनों को एक जैसा, محمد, लिखती थी, इसलिए जो भी भेद था, वह नाम को बोलकर पढ़ने के ढंग में था।</p><h3>पश्चिम अफ़्रीका और कॉकेशस</h3><p>हाउसा खाने में <strong>Muhammadu</strong> है — 2015 से 2023 तक नाइजीरिया के राष्ट्रपति रहे मुहम्मदु बुहारी का नाम — और इस नाम का रोज़मर्रा का पुकार-रूप <em>Mamman</em> है। हाउसा व्यंजन पर ख़त्म होने वाले कई अरबी उधार शब्दों के अंत में एक स्वर जोड़ देती है: <em>al-kitāb</em> से <em>littafi</em> “किताब”, <em>al-aḥad</em> से <em>Lahadi</em> “रविवार”। और पश्चिम में, वोलोफ़, फ़ुला और मांडिंग बोलने वालों के बीच, यह नाम सिकुड़कर <strong>Mamadou</strong> हो जाता है, जिसे फ़्रांसीसी ढंग से /u/ के लिए <em>ou</em> से लिखा जाता है। मामादू दिया ने 1960 में स्वतंत्रता से लेकर 1962 तक सेनेगल की सरकार का नेतृत्व किया; मामादू तांजा 1999 से 2010 तक नाइजर के राष्ट्रपति रहे। Mamadou नक्शे के वंश-वृक्ष में तो है, पर उसका कोई खाना नहीं है, क्योंकि 43 खानों में से कोई भी फ़्रांसीसी-भाषी पश्चिम अफ़्रीका में नहीं पड़ता।</p><p>रूसी खाने में <strong>Магомед</strong> <em>Magomed</em> है, जो दागिस्तान और चेचन्या में प्रचलित रूसी रूप है। रूसी लंबे समय से विदेशी <em>h</em> को г से लिखती आई है, जैसे Hamburg के लिए Гамбург, और पुराने रूसी ग्रंथ पैग़ंबर को Магомет कहते हैं, जो मध्ययुगीन यूरोपीय <em>Mahomet</em> से आया है। क्रोएशियाई खाने में बोस्नियाई <strong>Muhamed</strong> है, और उत्तरी अफ़्रीकी परिवारों के साथ आया फ़्रांसीसी रूप <strong>Mohamed</strong> है। दोनों में एक ही <em>m</em> लिखा जाता है।</p><h3>वर्तनियों की गिनती</h3><p>मुहम्मद को अक्सर दुनिया का सबसे आम नाम कहा जाता है, लेकिन व्यक्तिगत नामों का कोई विश्वव्यापी रजिस्टर नहीं है, और ऐसा कोई भी कुल योग इस पर निर्भर करता है कि Mehmet, Mamadou और Magomed को एक ही नाम गिना जाए या नहीं। राष्ट्रीय आँकड़े वर्तनियों को अलग-अलग गिनते हैं। ऑफ़िस फ़ॉर नेशनल स्टैटिस्टिक्स इंग्लैंड और वेल्स के नामों को ठीक वैसे ही क्रम देता है जैसे वे जन्म प्रमाणपत्रों पर लिखे हों; 2015 में इस हिसाब से Muhammad 12वें, Mohammed 29वें और Mohammad 68वें स्थान पर था, और मुहम्मद को लड़कों का शीर्ष नाम बताने वाली सुर्ख़ियाँ वर्तनियों को जोड़ने से निकली थीं।</p><p>2023 से अकेली वर्तनी Muhammad बिना इस मदद के पहले स्थान पर है। 2025 में इंग्लैंड और वेल्स में 5,957 लड़के Muhammad नाम से दर्ज हुए, जबकि दूसरे स्थान पर रहे Noah के 4,075 थे। इसके अलावा 1,712 लड़के Mohammed (20वाँ स्थान), 895 Mohammad (55वाँ), 385 Muhammed और 240 Mohamed नाम से दर्ज हुए। अकेले वेल्स में Muhammad 34वें स्थान पर था।</p>","alexander-iskandar-sikandar":"<h3>गायब पहला अक्षर</h3><p>मानचित्र पर यूनानी खाने में <strong>Αλέξανδρος</strong> <em>Aléxandros</em> लिखा है। पूर्व की ओर सात खानों में यही नाम अपने पहले अक्षर के बिना मिलता है: अरबी <strong>إسكندر</strong> <em>Iskandar</em>, फ़ारसी <strong>اسکندر</strong> <em>Eskandar</em>, तुर्की <strong>İskender</strong>, उर्दू <strong>سکندر</strong> और हिंदी <strong>सिकंदर</strong> <em>Sikandar</em>, तथा मलय और इंडोनेशियाई <strong>Iskandar</strong>।</p><p>जिन दो भाषाओं ने सिकंदर की कहानी को निकट पूर्व तक पहुँचाया, उन दोनों ने यह अक्षर बनाए रखा। लगभग 630 में लिखी गई सिरियाक सिकंदर-कथा उसे <em>Aleksandrōs</em> कहती है। मध्य फ़ारसी के ज़रथुश्त्री लेखन में, <em>अर्दा विराज़ की पुस्तक</em> में, उसे <em>gizistag Aleksandar ī Hrōmāyīg</em> यानी “अभिशप्त सिकंदर, रोमी” कहा गया है। पुस्तक के अनुसार उसने ईरान के शासक को मारा, उसकी राजधानी को उजाड़ा और अवेस्ता को जला दिया। यह अक्षर अरबी में खोया, जहाँ <em>Al-</em> ठीक निश्चयवाचक उपपद <em>al-</em> (अंग्रेज़ी “the”) जैसा सुनाई देता है। बोलने वालों ने नाम को <em>al-</em> + <em>eksandar</em> में बाँट दिया और उपपद हटा दिया, जैसा वे किसी भी संज्ञा के साथ कर सकते थे। इसके बाद दो और बदलाव हुए। यूनानी <em>ks</em> (ξ) <em>sk</em> बन गया, और चूँकि अरबी में शब्द दो व्यंजनों से शुरू नहीं होता, बचे हिस्से के आगे एक स्वर जुड़ गया: <em>Iskandar</em>। शहर के साथ भी यही हुआ। अलेक्ज़ेंड्रिया अरबी में <em>al-Iskandariyya</em> है, जिसमें उपपद फिर लौट आया है, पर इस बार सचमुच के उपपद के रूप में।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setname\" data-name=\"alexander\">👤 मानचित्र पर अलेक्ज़ेंडर देखें</button></div><h3>एस्कंदर और सिकंदर</h3><p>फ़ारसी ने अरबी रूप अपनाया और दूसरी तरफ़ से उसी समस्या से टकराई, क्योंकि फ़ारसी भी शब्द की शुरुआत में <em>sk-</em> से बचती है। उसने इसे दो तरीक़ों से सुलझाया। <em>Eskandar</em> स्वर को आगे रखता है। <em>Sekandar</em>, या शास्त्रीय और दक्षिण एशियाई उच्चारण में <em>Sikandar</em>, स्वर को व्यंजनों के बीच रख देता है। फ़िरदौसी के <em>शाहनामा</em> (लगभग 1010 में पूरा) में एस्कंदर फ़ारसी राजा दाराब और मकदूनिया के फ़िलिप की एक बेटी का पुत्र है, यानी ईरान का विजेता आधा ईरानी है। 12वीं सदी के उत्तरार्ध में निज़ामी ने उस पर एक पूरा काव्य लिखा, <em>एस्कंदर-नामे</em>।</p><p>उर्दू और हिंदी को <em>Sikandar</em> फ़ारसी से मिला, जो दिल्ली सल्तनतों और मुग़ल दरबार की भाषा थी। सुल्तान सिकंदर लोदी ने 1489 से 1517 तक दिल्ली पर शासन किया। हैदराबाद का जुड़वाँ शहर सिकंदराबाद निज़ाम सिकंदर जाह (शासनकाल 1803–1829) के नाम पर है।</p><h3>दो सींगों वाला</h3><p>क़ुरआन की सूरा 18 (आयतें 83–101) <em>ज़ुल-क़रनैन</em> (Dhū al-Qarnayn), “दो सींगों वाला”, की कथा कहती है। वह वहाँ तक जाता है जहाँ सूरज डूबता है और वहाँ तक जहाँ वह उगता है, और याजूज-माजूज को रोकने के लिए लोहे की दीवार बनाता है। पाठ में सिकंदर का नाम कहीं नहीं आता। 1890 में थियोडोर नोल्डेके और 2008 में केविन वैन ब्लेडेल ने इस अंश की तुलना सिरियाक सिकंदर-कथा से की, जिसमें सिकंदर वही यात्रा करता है और उन्हीं जातियों के विरुद्ध एक द्वार बनाता है। वैन ब्लेडेल का तर्क है कि क़ुरआन की ये आयतें उसी कथा को फिर से कहती हैं, जो मुहम्मद के जीवन के अंतिम वर्षों में प्रचलित थी। सींगों का एक प्रस्तावित स्रोत स्वयं सिकंदर की एक छवि है। 332 ईसा पूर्व में मिस्र जीतने के बाद उसे देवता आमोन के मेढ़े वाले सींगों के साथ दिखाया गया, और यह छवि उसके उत्तराधिकारी लाइसिमैकस के ढलवाए सिक्कों पर मिलती है।</p><p>अधिकांश शास्त्रीय टीकाकारों ने माना कि ज़ुल-क़रनैन सिकंदर ही था, पर सबने नहीं। इब्न कसीर का मत था कि क़ुरआनी पात्र एक पहले का राजा और ईमानवाला था, और मकदूनिया का सिकंदर, जो बहुदेववादी था, कोई दूसरा व्यक्ति था। कुछ आरंभिक वृत्तांतों ने उसकी जगह यमन के एक हिम्यरी राजा का नाम लिया। 19वीं और 20वीं सदी में सैयद अहमद ख़ान और अबुल कलाम आज़ाद ने तर्क दिया कि वह कुरुष महान (साइरस) था। सिकंदर से जुड़ाव इस अंश को पढ़ने के ढंग से आता है; पाठ स्वयं यह संबंध नहीं जोड़ता।</p><p>मलय जगत में यूनानी नाम और क़ुरआनी उपाधि एक हो जाते हैं। मलय इतिवृत्त (<em>Sejarah Melayu</em>, जिसका सबसे पुराना संस्करण 1612 का है) मलक्का के राजाओं की वंशावली <em>Raja Iskandar Zulkarnain</em>, “दो सींगों वाले राजा सिकंदर”, तक ले जाता है। <em>Hikayat Iskandar Zulkarnain</em> उसका जीवन फिर से सुनाती है, शायद किसी अरबी रोमांस-कथा के आधार पर। राजवंश यह नाम रखते रहे: सुल्तान इस्कंदर मुदा ने 1607 से 1636 तक आचे पर शासन किया। मानचित्र पर मलय और इंडोनेशियाई, दोनों खानों में <strong>Iskandar</strong> है।</p><h3>शांडोर: दूसरा सिरा</h3><p>हंगेरियन ने नाम को दूसरे सिरे से काटा। लाडो और बीरो की <em>Magyar utónévkönyv</em> (2005) <strong>Sándor</strong> को अलेक्ज़ेंडर के एक संक्षिप्त रूप का हंगेरियन संस्करण बताती है। इसमें <em>-sander</em> वाला हिस्सा बचा है, नाम का वही टुकड़ा जिसे मानचित्र डच (<em>Sander</em>) और जॉर्जियाई (<em>Sandro</em>) में उपनाम के रूप में दिखाता है। हंगेरियन वर्तनी में <em>s</em> का उच्चारण /ʃ/ होता है, इसलिए नाम [ˈʃaːndor] बोला जाता है, यानी इसकी शुरुआत हिंदी के <em>श</em> से होती है। कवि शांडोर पेटोफ़ी (1823–1849) का यही नाम था, और रोज़मर्रा का उपनाम <em>Sanyi</em> है।</p>","theophoric-names":"<h3>एक नाम जो सवाल पूछता है</h3><p>हिब्रू नाम <strong>Mīḵāʼēl</strong> अपने-आप में एक पूरा वाक्य है: <em>mī</em> “कौन”, <em>kā</em> “जैसा”, <em>ʼēl</em> “ईश्वर”, यानी “ईश्वर जैसा कौन?”। किसी देवता के लिए प्रयुक्त शब्द के इर्द-गिर्द बने नाम को <strong>थियोफ़ोरिक</strong> नाम कहते हैं, और इस मानचित्र के 50 नामों में से कम से कम नौ इसी तरह के हैं। हिब्रू बाइबिल में ऐसे दो तत्व मिलते हैं। एक है <em>ʼēl</em>, जो “ईश्वर” के लिए सामान्य सामी शब्द है। दूसरा है दिव्य नाम YHWH का संक्षिप्त रूप, जो नाम की शुरुआत में <em>Yeho-</em> या <em>Yo-</em> और अंत में <em>-yah</em> या <em>-yāhū</em> लिखा जाता है।</p><ul><li><strong>अंत में -el:</strong> माइकल; गेब्रियल, <em>Gaḇrīʼēl</em>, जिसका अर्थ मानचित्र पर “ईश्वर मेरी शक्ति है” दिया गया है (पहला हिस्सा धातु g-b-r “बलवान होना” से है, जिससे <em>gever</em> “पुरुष” भी बना है, इसलिए “ईश्वर का पुरुष” भी एक अर्थ हो सकता है); डैनियल, <em>Dāniyyēl</em>, “ईश्वर मेरा न्यायाधीश है”।</li><li><strong>शुरुआत में El-:</strong> एलिज़ाबेथ, <em>Elišévaʿ</em>, “मेरा ईश्वर एक शपथ है”, जो निर्गमन 6:23 में हारून की पत्नी का नाम है।</li><li><strong>Yah:</strong> जॉन, <em>Yōḥānān</em>, “याहवे कृपालु है”; मैथ्यू, <em>Mattityāhū</em>, “याहवे का उपहार”।</li><li><strong>दोनों एक साथ:</strong> एलायजा, <em>ʼĒlīyāhū</em>: <em>ʼēlī</em> “मेरा ईश्वर” + <em>yāhū</em>, यानी “मेरा ईश्वर याहवे है”।</li></ul><p>जोसेफ़, <em>Yōsēf</em> “वह बढ़ाएगा”, एक सीमांत मामला है। अपने मौजूदा रूप में इसमें कोई दिव्य तत्व नहीं है, लेकिन भजन संहिता 81:6 (अंग्रेज़ी बाइबिलों में 81:5) में इसे <em>Yehōsēf</em> लिखा गया है, यानी दिव्य तत्व के साथ। इससे लगता है कि छोटा नाम “ईश्वर बढ़ाए” का कटा हुआ रूप है।</p><h3>भाषाओं ने ईश्वर के साथ क्या किया</h3><p>जब ये नाम हिब्रू से बाहर निकले, तो इन्हें इस्तेमाल करने वालों के लिए ईश्वर-वाचक शब्द का कोई अर्थ नहीं रह गया। वह मात्र ध्वनि बन गया, और हर भाषा ने उसे अपने ढंग से ढाल लिया:</p><ul><li><strong>माइकल:</strong> रूसी Михаил <em>Mikhail</em> इसे <em>-il</em> के रूप में बचाए रखता है, पोलिश में Michał और हंगेरियन में Mihály है, और रोमानियाई <em>Mihai</em> ने अंतिम <em>l</em> खो दिया है।</li><li><strong>एलिज़ाबेथ:</strong> स्पेनिश और पुर्तगाली <em>Isabel</em> ने शुरुआती <em>El-</em> खो दिया (मध्यकालीन ऑक्सिटन में <em>Elisabel</em> था), और हंगेरियन <em>Erzsébet</em> ने उसे <em>Er-</em> बना दिया।</li><li><strong>एलायजा:</strong> <em>ʼēlī</em> बन गया <em>Il-</em>, और <em>-yāhū</em> सिकुड़ गया या गायब हो गया: रूसी Илья <em>Ilya</em>, रोमानियाई <em>Ilie</em>, हंगेरियन <em>Illés</em>।</li><li><strong>मैथ्यू:</strong> नाम के यूनानी तक पहुँचने से पहले ही याहवे खो चुका था, क्योंकि यूनानी <em>Maththaîos</em> अरामी संक्षिप्त रूप <em>Mattay</em> से आया है। मानचित्र पर स्पेनिश <em>Mateo</em> और रूसी Матвей <em>Matvei</em> हैं।</li><li><strong>जॉन:</strong> डच, पोलिश और चेक <em>Jan</em>, रूसी Иван <em>Ivan</em> और आयरिश <em>Seán</em> में <em>Yō-</em> घटकर सिर्फ़ एक आरंभिक ध्वनि रह गया है।</li></ul><h3>ईश्वर का उपहार, यूनानी में</h3><p><strong>थियोडोर</strong> यूनानी <em>Theódōros</em> है, जो <em>theós</em> “ईश्वर” और <em>dōron</em> “उपहार” से बना है। इसका अर्थ वही है जो मैथ्यू का है, और डोरोथिया में यही दो हिस्से उलटे क्रम में हैं। जिन स्लाव लोगों ने यह नाम अपनाया, उनके पास <em>th</em> ध्वनि नहीं थी, इसलिए उन्होंने यूनानी थीटा की जगह <em>f</em> रख दिया; इसी से रूसी Фёдор <em>Fyodor</em> और यूक्रेनी Федір <em>Fedir</em> बने। मानचित्र पर हंगेरियन <em>Tivadar</em>, रोमानियाई <em>Tudor</em> और अम्हारिक ቴዎድሮስ <em>Tewodros</em> भी हैं, जो इथियोपिया के सम्राट तेवोद्रोस द्वितीय (शासन 1855–1868) का नाम था।</p><h3>ईश्वर का दास, अरबी में</h3><p><strong>ʿAbd Allāh</strong> है <em>ʿabd</em> “दास” + <em>Allāh</em> “ईश्वर”। हिब्रू के बाहर माइकल का अर्थ कोई नहीं समझ पाता, लेकिन अब्दुल्लाह आज भी ऐसे दो शब्दों में टूट जाता है जिन्हें कोई भी अरबी भाषी समझता है। अधिकांश अरबी-विद्वान <em>Allāh</em> को <em>al-ilāh</em> “वह ईश्वर” से व्युत्पन्न मानते हैं, और <em>ilāh</em> हिब्रू <em>ʼēl</em> से संबंधित है; अल्पसंख्यक विद्वान इसका स्रोत अरामी <em>alāhā</em> में देखते हैं। यह परिपाटी इस्लाम से भी पुरानी है। मुहम्मद के पूर्वज अब्द मनाफ़ का नाम देवता मनाफ़ के नाम पर रखा गया था, और मुहम्मद के पिता का नाम पहले से ही अब्दुल्लाह था। सहीह मुस्लिम (संख्या 2132) में इब्न उमर बताते हैं कि पैगंबर ने अब्दुल्लाह और अब्दुर्रहमान को ईश्वर को सबसे प्रिय नाम बताया।</p><p>मानचित्र पर अरबी खाने में इसे दो स्वरचिह्नित शब्दों में लिखा गया है, عَبْد اللّٰه, और सऊदी खाने में दोनों को जोड़कर عبدالله। अन्यत्र यह फ़ारसी <em>Abdollah</em>, हौसा <em>Abdullahi</em>, स्वाहिली <em>Abdala</em>, फ़्रांसीसी <em>Abdallah</em>, क्रोएशियाई खाने में बोस्नियाई रूप <em>Abdulah</em> और चीनी 阿卜杜拉 <em>Ābǔdùlā</em> के रूप में मिलता है।</p><p>मानचित्र के संस्कृत नाम अलग ढंग से काम करते हैं। कृष्ण, राम, गणेश और लक्ष्मी स्वयं देवताओं के नाम हैं जो बच्चों को सीधे दिए जाते हैं, किसी देवता के बारे में वाक्य नहीं।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setname\" data-name=\"michael\">👤 मानचित्र पर माइकल देखें</button><button type=\"button\" class=\"trivia-action\" data-action=\"setname\" data-name=\"abdullah\">👤 मानचित्र पर अब्दुल्लाह देखें</button></div><h3>फ़रिश्तों ने अपना -el बचाए रखा</h3><p>जहाँ फ़रिश्तों के नाम अरबी के रास्ते पहुँचे, वहाँ पुराना <em>ʼēl</em> आज भी <em>-īl</em> के रूप में मौजूद है। मानचित्र पर अरबी ميكائيل <em>Mīkāʼīl</em> और جبريل <em>Jibrīl</em>, तुर्की <em>Mikail</em> और <em>Cebrail</em>, तथा फ़ारसी میکائیل <em>Mikaʼil</em> और جبرئیل <em>Jabraʼil</em> दिखते हैं।</p>","nicholas-santa-claus":"<h3>एक संत के साथ चला यूनानी नाम</h3><p>यूनानी <strong>Νικόλαος</strong> (<em>Nikólaos</em>) में <em>níkē</em> \"विजय\" और <em>laós</em> \"जनता\" जुड़े हैं। यह नाम अपनी ईसाई प्रसिद्धि से पुराना है: दमिश्क के निकोलाउस ने ईसा पूर्व पहली सदी में हेरोद के दरबार में इतिहास-ग्रंथ लिखे, और प्रेरितों के काम 6:5 में सात डीकनों में अंताकिया के निकोलाउस का नाम आता है। फिर भी पूरे यूरोप में इसका प्रसार एक ही व्यक्ति के पीछे-पीछे हुआ: लीकिया में मीरा के बिशप निकोलस, जो आज के तुर्की के अंताल्या प्रांत में देमरे के पास था, और जिनकी पारंपरिक तिथियाँ 270–343 हैं। उनके जीवनकाल का, उनका लिखा या उनके बारे में लिखा, कुछ भी नहीं बचा है। उनकी सबसे पुरानी पूरी <em>जीवनी</em>, जो आर्किमंड्राइट माइकल ने लिखी, नौवीं सदी की शुरुआत की है, और उपहार वाली किंवदंती का पहला स्रोत यही है: एक ग़रीब आदमी की तीन बेटियों को दहेज मिल सके, इसलिए खिड़की से चुपके से सोना फेंका गया। 1087 में बारी के नाविक उनकी अधिकांश अस्थियाँ दक्षिणी इटली ले गए, जहाँ वे 9 मई को पहुँचीं।</p><h3>एक संत, अनेक स्थानीय नाम</h3><p>चूँकि नाम को संत की उपासना ही आगे ले गई, इसलिए दिसंबर वाले संत का रूप हर जगह स्थानीय नाम से जाना जाता है। मानचित्र पर यूनानी मूल Νικόλαος के बगल में लैटिन से निकले रूप हैं: <strong>Nicolas</strong> (फ़्रेंच), <strong>Nicolás</strong> (स्पेनिश), <strong>Nicolau</strong> (पुर्तगाली), <strong>Niccolò</strong> (इतालवी) और <strong>Nicolae</strong> (रोमानियाई), साथ ही क्रोएशियाई में <strong>Nikola</strong>, जॉर्जियाई में <strong>ნიკოლოზ</strong> (Nikoloz) और आर्मेनियाई में <strong>Նիկոլ</strong> (Nikol)। और उत्तर व पूर्व की ओर पहला व्यंजन बदल जाता है: रूसी <strong>Николай</strong> (Nikolai) में उसे बनाए रखती है, पर यूक्रेनी में <strong>Микола</strong> (Mykola), पोलिश में <strong>Mikołaj</strong>, चेक में <strong>Mikuláš</strong> और हंगेरियन में <strong>Miklós</strong> है। चेक में नाम और प्रथा एक ही शब्द हैं: 5 दिसंबर की शाम मिकुलाश एक फ़रिश्ते और एक शैतान के साथ बच्चों से मिलने आता है। पोलैंड में उपहार लाने वाला Święty Mikołaj है, यानी \"संत निकोलस\"।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setname\" data-name=\"nicholas\">👤 मानचित्र पर निकोलस दिखाएँ</button><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"50\" data-lng=\"15\" data-zoom=\"4\">🌍 मध्य यूरोप में Nikolaus, Mikuláš और Miklós की तुलना करें</button></div><h3>अंत, शुरुआत या बीच से बने छोटे रूप</h3><p>कई छोटे रूप नाम का आरंभ छोड़ देते हैं। जर्मन <strong>Nikolaus</strong> से <em>Klaus</em> और डच <strong>Nicolaas</strong> से <em>Klaas</em> बनता है; डेनिश <em>Niels</em> और स्वीडिश <em>Nils</em> लैटिन <em>Nicolaus</em> के मध्यकालीन संक्षिप्त रूप हैं, जबकि मानचित्र पर स्वीडिश खाने में अधिक पूरा रूप <strong>Niklas</strong> दिखता है। दूसरे छोटे रूप इसके उलट शुरुआत को बचाए रखते हैं: अंग्रेज़ी <em>Nick</em>, यूनानी <em>Nikos</em>। रूसी <em>Kolya</em> बीच के अक्षर पर बना है। डच संत Sint Nicolaas भी इसी तरह घिसकर <strong>Sinterklaas</strong> बन गए।</p><h3>सिंटरक्लास से सांता क्लॉज़ तक</h3><p>अंग्रेज़ी नाम पहली बार न्यूयॉर्क में दर्ज हुआ। दिसंबर 1773 में <em>New-York Gazette and the Weekly Mercury</em> और <em>Rivington's New-York Gazetteer</em> ने ख़बर दी कि संत निकोलस, \"जिन्हें St. A Claus भी कहा जाता है\", की वर्षगाँठ प्रोटेस्टेंट हॉल में मनाई गई। <em>Salmagundi</em> — वह पत्रिका जिसे वॉशिंगटन इरविंग ने अपने भाई विलियम और जेम्स कर्क पॉल्डिंग के साथ लिखा — के 1808 के एक अंक में \"प्रसिद्ध संत निकोलस, जिन्हें आम बोलचाल में Santaclaus कहा जाता है\" का उल्लेख है। इरविंग की 1809 की <em>History of New York</em>, जिसे एक डच इतिहासकार डीड्रिक निकरबॉकर की रचना के रूप में पेश किया गया था, संत निकोलस को डच न्यू एम्स्टर्डम का संरक्षक संत बनाती है। दिसंबर 1810 में न्यूयॉर्क हिस्टोरिकल सोसाइटी ने, जिसकी स्थापना जॉन पिंटार्ड ने 1804 में की थी, संत निकोलस की वर्षगाँठ पर अपना पहला भोज आयोजित किया, और पिंटार्ड ने संत की उत्कीर्ण छवि वाले एक ब्रॉडसाइड (एक तरफ़ छपे पर्चे) का ख़र्च उठाया।</p><p>न्यूयॉर्क वाले इस किरदार को किसने गढ़ा, इस पर विद्वान एकमत नहीं हैं। चार्ल्स डब्ल्यू. जोन्स को \"Knickerbocker Santa Claus\" (1954) में डच उपनिवेश के अभिलेखों में संत निकोलस के पर्व का बहुत कम निशान मिला, और उन्होंने इस किरदार को रचने का श्रेय इरविंग की मंडली को दिया; यही मत मानक बन गया। टॉम ए. जरमन (2022) बताते हैं कि इरविंग की <em>History</em> के 1809 संस्करण में संत निकोलस का सोलह बार उल्लेख है, पर केवल संरक्षक संत के रूप में, सांता क्लॉज़ के रूप में कभी नहीं, और उपहार देने वाले अंश पहली बार 1812 के संस्करण में आते हैं। इसलिए वे सांता क्लॉज़ के गढ़े जाने को 1821–1823 का मानते हैं, और नीचे दिए दो पाठों से जोड़ते हैं।</p><p>रेनडियर पहली बार 1821 में दिखते हैं, <em>The Children's Friend</em> में — न्यूयॉर्क में विलियम बी. गिली द्वारा प्रकाशित आठ पन्नों की एक पुस्तिका, जिसमें \"Santeclaus\" एक ही रेनडियर हाँकता है। 23 दिसंबर 1823 को <em>Troy Sentinel</em> ने \"Account of a Visit from St. Nicholas\" बिना लेखक के नाम के छापी। क्लेमेंट क्लार्क मूर ने इसे 1844 के अपने <em>Poems</em> में शामिल किया; हेनरी लिविंगस्टन जूनियर के वंशजों ने उनके लेखकत्व पर आपत्ति की, और डॉन फ़ॉस्टर ने 2000 में लिविंगस्टन के पक्ष में तर्क रखे। कविता अपने आगंतुक को St. Nicholas और St. Nick कहती है, Santa Claus कभी नहीं। उसके आख़िरी दो रेनडियर <em>Dunder</em> और <em>Blixem</em> थे, जो डच <em>donder</em> \"गरज\" और <em>bliksem</em> \"बिजली\" से आए; बाद के संस्करणों ने इन्हें Donder और Blitzen कर दिया।</p><h3>लाल पोशाक कोका-कोला से पहले आई</h3><p>थॉमस नैस्ट ने 3 जनवरी 1863 के अंक से <em>Harper's Weekly</em> के लिए सांता क्लॉज़ के चित्र बनाए, और लगभग तीस वर्षों में उनके सांता का कोट हल्के भूरे से लाल हो गया। 1900 के दशक की शुरुआत में <em>Puck</em> के आवरणों पर लाल-सफ़ेद सांता दिखते थे। कोका-कोला के लिए हैडन सनडब्लॉम का सांता पहली बार 1931 में <em>The Saturday Evening Post</em> में छपा, और सनडब्लॉम ने कंपनी के लिए अपना आख़िरी संस्करण 1964 में बनाया। कंपनी का अपना इतिहास-पृष्ठ कहता है कि सनडब्लॉम के चित्र बनाने से पहले भी सांता लाल पहनते थे। विज्ञापनों ने चेहरे और डील-डौल का एक रूप पक्का कर दिया, पर रंग पहले से मौजूद था।</p>","george-yuri-yegor":"<h3>किसान का नाम, सैनिक की पूजा</h3><p>यूनानी <em>Geṓrgios</em> (Γεώργιος) <em>geōrgós</em> यानी “किसान” पर बना है, जो <em>gē</em> “धरती” और <em>ergon</em> “काम” से मिलकर बना है। खेती पर वर्जिल की काव्य-रचना <em>जॉर्जिक्स</em> (29 ईसा पूर्व) का शीर्षक भी इसी शब्द से आया है। यह नाम एक व्यक्ति के कारण फैला: एक सैनिक, जिसके बारे में परंपरा कहती है कि वह लिड्डा (डियोस्पोलिस, आज इज़राइल का लोद) में या उसके आसपास शहीद हुआ। उसकी शहादत पारंपरिक रूप से डायोक्लीशियन के शासनकाल में सन् 303 की मानी जाती है। ड्रैगन बाद में आया। उस कथा का सबसे पुराना ज्ञात रूप 11वीं सदी के एक जॉर्जियाई स्रोत में मिलता है। 12वीं सदी में यह कथा लैटिन यूरोप पहुँची, और लगभग 1260 में याकोबुस दे वोरागिने की <em>गोल्डन लेजेंड</em> ने इसे पश्चिमी पाठकों के लिए पक्का कर दिया।</p><h3>रूसी में तीन नाम</h3><p>रूसी में यह नाम तीन रूपों में मिलता है, और तीनों आज तक बचे हुए हैं। प्राचीन पूर्वी स्लाव का लोक-रूप <em>Gjurgi</em> (Гюрги) बना <strong>Юрий</strong> <em>यूरी</em>। एक दूसरे लोक-रूप <em>Yegory</em> (Егорий) ने शुरुआती <em>G-</em> छोड़ दिया और छोटा होकर <strong>Егор</strong> <em>येगोर</em> बन गया। चर्च ने यूनानी रूप <strong>Георгий</strong> <em>गेओर्गी</em> बनाए रखा। मैक्स फ़ास्मर का रूसी व्युत्पत्ति-कोश तीनों को <em>Geōrgios</em> तक ले जाता है। आज ये अलग-अलग नाम हैं और इनके लघु-रूप भी अलग हैं, इसलिए नक्शे पर रूसी का खाना <em>Юрий / Георгий</em> दिखाता है और यूरी गागारिन के साथ गेओर्गी ज़ुकोव का नाम देता है — दो व्यक्ति, जिनके नाम एक ही संत पर रखे गए। यूक्रेनी भी यही करती है: रोज़मर्रा का <em>Юрій</em> <em>Yuriy</em> और विद्वत्तापूर्ण <em>Heorhiy</em>।</p><p>कीवी रूस में यूरी राजकुमारों का नाम था। यारोस्लाव द वाइज़ (बुद्धिमान यारोस्लाव) का बपतिस्मा-नाम यूरी था, और <em>प्राइमरी क्रॉनिकल</em> के अनुसार लगभग 1030 में उन्होंने आज के एस्टोनिया में तार्तू की जगह पर एक क़िला बनवाया और उसका नाम यूर्येव रखा। रूसी साम्राज्य ने 1893 में शहर को फिर से यही नाम दिया। इतिवृत्तों में मॉस्को का पहला उल्लेख 1147 में मिलता है, उस जगह के रूप में जहाँ राजकुमार यूरी डोल्गोरुकी ने एक सहयोगी का स्वागत किया था।</p><p>लोक-पंचांग में नाम के दोनों रूप चलते थे। 23 अप्रैल (जूलियन) का वसंत पर्व <em>Yegory Veshny</em>, यानी “वसंत का येगोरी”, कहलाता था। 26 नवंबर का शरद पर्व यूरी का दिन था, और 1497 की विधि-संहिता (सुदेब्निक) ने उससे पहले और बाद के एक-एक हफ़्ते को साल का अकेला ऐसा समय ठहराया जब कोई किसान एक ज़मींदार को छोड़कर दूसरे के पास जा सकता था। 1580 के दशक से “वर्जित वर्षों” के फ़रमानों ने यह अधिकार स्थगित कर दिया, और इस नुक़सान की याद इस कहावत में बची है: <em>Вот тебе, бабушка, и Юрьев день</em>, “लो दादी, हो गया यूरी का दिन”, जो किसी टूटे हुए वादे पर कही जाती है।</p><h3>पश्चिम और उत्तर</h3><p>लैटिन <em>Georgius</em> से फ़्रांसीसी <em>Georges</em>, स्पेनी और पुर्तगाली <em>Jorge</em>, इतालवी <em>Giorgio</em> और जर्मन <em>Georg</em> बने, और उसके साथ लो जर्मन में <em>Jürgen</em>। पुरानी चेक का <em>Juří</em> बना <strong>Jiří</strong>, जो 15वीं सदी के राजा यिर्झी ज़ पोदेब्राद का नाम था, और पुरानी पोलिश ने इसे चेक से <em>Jirzy</em> या <em>Jurzy</em> के रूप में उधार लिया, जो आगे चलकर <strong>Jerzy</strong> बना। और आगे पूर्व व दक्षिण में हंगेरियाई <em>György</em>, क्रोएशियाई <em>Juraj</em> और रोमानियाई <em>Gheorghe</em> हैं। उत्तर में स्वीडिश में <em>Göran</em> और <em>Örjan</em> हैं, और फ़िनिश <strong>Yrjö</strong> मध्यकालीन दस्तावेज़ों में <em>Yrjä</em> और <em>Yrjänä</em> के रूप में दर्ज है। डच में <em>Joris</em> है। इंग्लैंड में यह संत 14वीं सदी से संरक्षक संत रहे, पर नाम ख़ुद तब तक दुर्लभ रहा जब तक 1714 में जर्मनी में जन्मे जॉर्ज प्रथम गद्दी पर नहीं बैठे। तब से पाँच और ब्रिटिश राजा यह नाम धारण कर चुके हैं।</p><h3>जॉर्जिया, आर्मेनिया, इथियोपिया और अरब जगत</h3><p>नक्शे की टिप्पणी के अनुसार जॉर्जियाई <strong>Giorgi</strong> (გიორგი) जॉर्जिया का सबसे आम नाम है। फिर भी देश का नाम इस संत से नहीं लिया गया। जॉर्जियाई अपने देश को <em>Sakartvelo</em> कहते हैं। यूरोपीय <em>Georgia</em> संभवतः जॉर्जियाई लोगों के फ़ारसी नाम <em>gurğ</em> से आया है, जिससे पश्चिमी क्रूसेडर और तीर्थयात्री 11वीं और 12वीं सदी में लेवांत में परिचित हुए; रूसी <em>Gruziya</em> का स्रोत भी यही है। 13वीं सदी में ज़ाक द वित्री ने इस नाम को संत जॉर्ज के प्रति जॉर्जियाई लोगों की भक्ति से समझाया, और दूसरों ने इसे यूनानी <em>geōrgós</em> से जोड़ा। दोनों ही एक उधार लिए गए शब्द की बाद में गढ़ी गई व्याख्याएँ हैं।</p><p>आर्मेनियाई में <em>Gevorg</em> है, और पश्चिमी आर्मेनियाई में <em>Kevork</em>। अम्हारी <em>Giyorgis</em> (ጊዮርጊስ) इथियोपिया के संरक्षक संत का नाम है, और लालिबेला में चट्टान काटकर बने क्रॉस-आकार के चर्च बेते गियोर्गिस का भी। अरबीभाषी ईसाई इस संत को <em>Mār Jirjis</em> (جرجس) कहते हैं, और फ़्रांसीसी या अंग्रेज़ी से आया <em>Jūrj</em> भी इस्तेमाल करते हैं।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setname\" data-name=\"george\">👤 नक्शे पर जॉर्ज दिखाएँ</button><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"31.95\" data-lng=\"34.89\" data-zoom=\"6\">🌍 लोद (लिड्डा) जाएँ, शहादत की परंपरा का स्थान</button></div>","elizabeth-isabel":"<h3>एलीशेबा से एलिसाबेत तक</h3><p>निर्गमन 6:23 में हारून अम्मीनादाब की बेटी <strong>एलीशेबा</strong> (אֱלִישֶׁבַע, <em>Elišévaʿ</em>) से विवाह करता है। यह नाम <em>ʾēlî</em> \"मेरा ईश्वर\" और <em>šebaʿ</em> \"शपथ\" को जोड़ता है, और इसका अनुवाद आमतौर पर \"मेरा ईश्वर शपथ है\" किया जाता है। यूनानी सेप्टुआजिंट ने इसे <em>Elisabeth</em> (Ἐλισάβεθ) लिखा। यूनानी में <em>sh</em> ध्वनि नहीं थी, इसलिए <em>š</em> बदलकर <em>s</em> हो गया, अंत का हिब्रू <em>ʿ</em> लुप्त हो गया, और नाम के अंत में <em>-th</em> जुड़ गया, जो हिब्रू में नहीं है। लूका 1:5 यही नाम, Ἐλισάβετ वर्तनी में, यूहन्ना बपतिस्मा देने वाले की माँ को देता है। मानचित्र पर हर ईसाई रूप नए नियम की इसी एलिसाबेत से निकला है, और हिब्रू वाला खाना मूल रूप दिखाता है।</p><h3>पूर्वी और मध्य रूप</h3><p>बीज़ान्टिनी काल तक यूनानी <em>β</em> का उच्चारण [v] होने लगा था, जैसा आधुनिक यूनानी Ελισάβετ (<em>Elisávet</em>) में आज भी है। चर्च स्लावोनिक ने यह नाम इसी <em>v</em> के साथ लिया: लूका के सुसमाचार में Елисавет है, और चर्च कैलेंडर में स्त्रीलिंग <em>-a</em> के साथ Елисавета (<em>Yelisaveta</em>)। धर्मनिरपेक्ष रूसी में <em>s</em> की जगह <em>z</em> है: Елизавета (<em>Yelizaveta</em>), जो मानचित्र पर दिखाया गया रूप है। इस नाम की सबसे प्रसिद्ध धारक साम्राज्ञी येलिज़ावेता पेत्रोव्ना हैं, जिन्होंने 1741 से 1762 तक रूस पर शासन किया। आर्मेनियाई में यह Եղիսաբեթ (<em>Yeghisabet</em>) है।</p><p>और आगे पश्चिम में, तीन पड़ोसी भाषाओं ने नाम को मिलते-जुलते ढंग से छोटा किया। पोलिश <strong>Elżbieta</strong>, चेक <strong>Alžběta</strong> और हंगेरियन <strong>Erzsébet</strong> — तीनों पहले <em>l</em> के बाद का स्वर हटा देती हैं, और तीनों <em>s</em> को \"zh\" ध्वनि ([ʒ], पोलिश में [ʐ]) में बदल देती हैं, जिसे <em>ż</em>, <em>ž</em> और <em>zs</em> लिखा जाता है। इसके अलावा हंगेरियन में वहाँ <em>r</em> है जहाँ बाकी दोनों में <em>l</em> है। इस क्षेत्र में यह नाम हंगरी की संत एलिज़ाबेथ (1207–1231) से जुड़ा था, जो राजा एंड्रयू द्वितीय की बेटी थीं और जिन्हें 1235 में संत घोषित किया गया।</p><h3>इसाबेल: ओक्सितान रास्ते से होकर</h3><p><strong>इसाबेल</strong> (Isabel) को आमतौर पर एलिज़ाबेथ का स्पेनिश रूप कहा जाता है। लेकिन <em>Dictionary of Medieval Names from European Sources</em> इसकी जड़ पुरानी प्रोवेन्साल (ओक्सितान) <em>Elisabel</em> में बताता है, और इसके सबसे पुराने अभिलेख फ़्रांस से मिलते हैं: लगभग 823 में सैं-जर्मैं-दे-प्रे की संपत्ति-सूची में लैटिन <em>Isabel</em>, और 1135 में क्लेरवो में <em>Ysabel</em>। उसी शब्दकोश में पहली इबेरियाई प्रविष्टि 1487 की लैटिन <em>Isabel</em> है। यह तारीख़ शब्दकोश के नमूना-चयन को दर्शाती है, पहले प्रयोग को नहीं: पुर्तगाल की रानी, आरागॉन की इसाबेल, का निधन 1336 में हुआ था। पहले अक्षर के गायब होने की आम व्याख्या यह है कि बोलने वालों ने <em>El-</em> को रोमांस भाषाओं का उपपद <em>el</em> समझा और हटा दिया। <em>-beth</em> से <em>-bel</em> में बदलाव की कोई सर्वमान्य व्याख्या नहीं है। एक सुझाव रोमांस <em>bel</em>, <em>bella</em> \"सुंदर\" की ओर इशारा करता है।</p><h3>दोनों ओर की रानियाँ</h3><p>शाही विवाह इस नाम को नए देशों तक ले गए। अंगूलेम की इसाबेला ने 1200 में इंग्लैंड के राजा जॉन से विवाह किया, और फ़्रांस की इसाबेला ने 1308 में एडवर्ड द्वितीय से। उसी शब्दकोश में Isabel के अंग्रेज़ी अभिलेख 1189 से और Elizabeth के 1279–80 से मिलते हैं। तब भी लोग जानते थे कि ये एक ही नाम हैं: 16वीं सदी के इंग्लैंड में एक ही स्त्री दोनों नामों से दर्ज हो सकती थी, और 17वीं सदी तक Isabel कभी-कभी Elizabeth के दुलार-रूप की तरह इस्तेमाल होता था। पूर्व में, ज़ाबेल — इसाबेल का आर्मेनियाई रूप — 1219 से 1252 तक किलिकियाई आर्मेनिया की रानी रहीं। कास्तील की इसाबेल प्रथम (1451–1504) 1474 में रानी बनीं, और एक दूसरी इसाबेल, इसाबेल द्वितीय, ने 1833 से 1868 तक स्पेन पर शासन किया।</p><p>इंग्लैंड में <strong>एलिज़ाबेथ</strong> (Elizabeth) एलिज़ाबेथ प्रथम (1558–1603) के शासनकाल से एक लोकप्रिय नाम रहा है। इस नाम की दूसरी रानी, एलिज़ाबेथ द्वितीय, ने 1952 से 2022 तक शासन किया।</p><h3>मानचित्र पर बहन-नाम</h3><p>स्पेन, मेक्सिको और पुर्तगाल <strong>Isabel</strong> का प्रयोग करते हैं, और ब्राज़ील <strong>Isabela</strong> का। अन्य देशों में दोनों रूप अलग-अलग नामों के रूप में चलते हैं। फ़्रांस में <strong>Élisabeth</strong> है, और उसका बहन-नाम Isabelle। इटली में <strong>Elisabetta</strong> और Isabella, रोमानिया में <strong>Elisabeta</strong> और Isabela, और फ़िलीपींस में <strong>Elizabeth</strong> और Isabel हैं। बाइबिल अनुवादों ने यूनानी पर आधारित पुराना रूप बनाए रखा। कोरियाई 엘리사벳 (<em>Ellisabet</em>) बाइबिल से आया है, जबकि 엘리자베스 अंग्रेज़ी से बाद में लिया गया शब्द है। अरबी أليصابات (<em>Alīṣābāt</em>) अरबी बाइबिलों में ज़कर्याह की पत्नी का नाम है, और एक दुर्लभ ईसाई व्यक्तिगत नाम भी।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setname\" data-name=\"elizabeth\">👤 मानचित्र पर एलिज़ाबेथ / इसाबेल दिखाएँ</button><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"49\" data-lng=\"17\" data-zoom=\"5\">🌍 Elżbieta, Alžběta, Erzsébet पर जाएँ</button></div>","rama-sita-southeast-asia":"<h3>हल-रेखा, और साँवला या मनोहर</h3><p>संस्कृत <em>sītā</em> एक साधारण संज्ञा है: मोनियर-विलियम्स का 1899 का शब्दकोश इसका अर्थ देता है “हल-रेखा, हल के फाल का निशान या लकीर”। ऋग्वेद 4.57.6 में सीता का आह्वान उस हल-रेखा के रूप में किया गया है जो धरती के फलों की अधिष्ठात्री है। वाजसनेयि संहिता (12.69–72) में एक अनुष्ठान में चार हल-रेखाएँ खींचते समय उसे संबोधित किया जाता है। महाकाव्य इस संज्ञा को एक कथा बना देता है। विदेह के राजा जनक यज्ञ के लिए भूमि जोत रहे होते हैं, तभी उन्हें हल-रेखा में एक शिशु कन्या मिलती है, और इसीलिए उसका विशेषण <em>Ayonijā</em> है, “जो गर्भ से उत्पन्न नहीं हुई”।</p><p>विशेषण के रूप में <em>rāma</em> के दो अर्थ हैं, और शब्दकोश उन्हें अलग-अलग रखता है। अथर्ववेद में इसका अर्थ है “साँवला, गहरे रंग का, काला”, और शब्दकोश इसकी तुलना <em>rātri</em> “रात” से करता है। महाभारत से आगे इसका अर्थ है “मनोहर, सुखद, आकर्षक, प्यारा, सुंदर”, जो धातु <em>ram-</em> “विश्राम करना, आनंदित होना” से बना है। यह नाम महाकाव्य के नायक से पुराना है। परंपरा ऋग्वेद के सूक्त 10.110 को राम जामदग्न्य से जोड़ती है, और परवर्ती हिंदू धर्म तीन रामों को गिनता है: परशुराम, बलराम (“बलवान राम”) और रामायण के रामचंद्र। चूँकि ये तीन हैं, इसलिए संस्कृत लेखक <em>rāma</em> का प्रयोग संख्या तीन के लिए भी कर सकते थे।</p><p>मानचित्र पर हिंदी में राम <em>Rām</em> और सीता <em>Sītā</em> हैं, और बांग्ला में রাম <em>Ram</em> और সীতা <em>Sita</em>। थाई रूप उपाधियों के साथ आते हैं: พระราม <em>Phra Ram</em> में सम्मानसूचक <em>phra</em> जुड़ा है, और นางสีดา <em>Nang Sida</em> में <em>nang</em>, जो किसी महिला के लिए प्रयुक्त उपाधि है। इंडोनेशियाई खाने में <em>Sinta</em> है, जो जावा के वायांग में नायिका का नाम है।</p><h3>रामकियेन</h3><p>थाईलैंड में इस महाकाव्य का रूप <em>रामकियेन</em> है। अयुत्थया काल के अधिकांश ग्रंथ तब नष्ट हो गए जब 1767 में बर्मी सेनाओं ने नगर को ध्वस्त कर दिया। आज पढ़ा जाने वाला पाठ राजा राम प्रथम (शासन 1782–1809) के समय संकलित हुआ, जिन्होंने उसका कुछ अंश स्वयं लिखा। उनके पुत्र राम द्वितीय ने इसे <em>खोन</em> मुखौटा-नाट्य के लिए रूपांतरित किया, और बैंकॉक के वाट फ्रा केओ की दीवारों पर इसकी कथा चित्रित है। फ्रा राम, फ्रा नाराई (विष्णु) के अवतार हैं, और रावण यहाँ थोत्साकन बन जाता है।</p><p>सिदा का जन्म संस्कृत कथा से भिन्न है। रामकियेन में वह लंका में थोत्साकन की अपनी पुत्री के रूप में जन्म लेती है। ज्योतिषी भविष्यवाणी करते हैं कि वह अपने पिता पर विपत्ति लाएगी, इसलिए थोत्साकन उसे त्याग देता है। थाईलैंड फ़ाउंडेशन द्वारा प्रकाशित सारांश आगे बताता है: एक तपस्वी उसे धरती माता को सौंपते हुए भूमि में गाड़ देता है, और सोलह वर्ष बाद उसे बाहर निकालकर उसका नाम सीता रखता है, यानी “हल के निशान”। यह तपस्वी स्वयं चनोक (जनक) है, एक राजा जो तपस्वी का जीवन जी रहा है। थाई कथा में वह हल लेकर उस स्थान को खोजता है, उसे पाता है और अपनी पुत्री के रूप में मिथिला ले आता है। कन्या अब भी हल-रेखा में ही मिलती है, पर अब हल-रेखा वह बच्ची लौटाती है जिसे वहाँ गाड़ा गया था, न कि वह जिसे धरती ने जन्म दिया।</p><h3>अयुत्थया और राम राजा</h3><p>परंपरागत रूप से अयुत्थया की स्थापना 1351 में मानी जाती है। इसका नाम संस्कृत <em>Ayodhyā</em> है, जो राम की राजधानी थी। यह शब्द <em>yudh</em> “युद्ध करना” पर बना है और इसका अर्थ है “जिससे युद्ध न किया जा सके”, यानी अजेय। नगर का आधिकारिक नाम क्रुंग थेप द्वारवती सी अयुत्थया था। बैंकॉक को यह औपचारिक नाम विरासत में मिला, और उसके लंबे रूप में आज भी <em>Mahintharayutthaya</em> शामिल है। जावा का योग्यकार्ता भी अयोध्या के नाम पर है। राजकीय उपाधियों में राम का नाम भी आता था। अयुत्थया के संस्थापक उथोंग इतिवृत्तों में रामाधिबोदी प्रथम के राजनाम से आते हैं, और 1279 से 1298 तक शासन करने वाले सुखोथाई के राजा राम खामहेंग, यानी “साहसी राम”, के नाम से जाने जाते हैं।</p><p>राम प्रथम से राम दशम तक की क्रमांकित शृंखला कहीं अधिक नई है। इसकी शुरुआत इंग्लैंड में शिक्षित वजिरावुध (शासन 1910–1925) से हुई। अपने शासन के उत्तरार्ध में उन्होंने स्वयं को <em>Phra Ram thi Hok</em>, “छठे राम”, कहना शुरू किया। एक ही नाम वाले शासकों को क्रमांक देने की यूरोपीय प्रथा के अनुसार, 1782 तक पीछे जाकर चक्री वंश के सभी राजाओं पर यह उपाधि लागू करने का श्रेय भी उन्हें दिया जाता है। थाई भाषा में किसी राजा की पहचान प्रायः उसके शासनकाल से की जाती है: <em>Ratchakan thi Ha</em>, “पाँचवाँ शासनकाल”, चुलालोंगकोर्न हैं। भूमिबोल (शासन 1946–2016) को “राम नवम” कहना मुख्यतः अंग्रेज़ी भाषा की आदत है। वंश के संस्थापक थाई में फ्रा फुत्थयोतफा चुलालोक के नाम से जाने जाते हैं, जो एक बुद्ध-प्रतिमा से लिया गया नाम है जिसे उनके पोते राम तृतीय ने उन्हें समर्पित किया था। उन्होंने स्वयं को कभी राम प्रथम कहलाते नहीं सुना। फिर भी यह नाम पहले से उनका था: 1782 में जब वे सिंहासन पर बैठे, तो उनकी राज्याभिषेक उपाधि <em>Phra Borommarachathirat Ramathibodi</em> से शुरू होती थी।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setname\" data-name=\"rama\">👤 मानचित्र पर राम दिखाएँ</button><button type=\"button\" class=\"trivia-action\" data-action=\"setname\" data-name=\"sita\">👤 मानचित्र पर सीता दिखाएँ</button></div>","abdullah-servant-names":"<p><strong>Abdullah</strong> दो शब्दों का वाक्यांश है जो दबकर एक नाम बन गया। अरबी <em>ʿabd</em> (عبد) का अर्थ है बंदा, या ख़ुदा की इबादत करने वाला; <em>Allāh</em> ख़ुदा है। दोनों मिलकर बनते हैं <strong>ʿAbd Allāh</strong>, “ख़ुदा का बंदा”। यह नाम मुसलमानों में आम है क्योंकि ख़ुदा के सामने विनम्रता इस्लाम का केंद्रीय मूल्य है।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setname\" data-name=\"abdullah\">👤 नक्शे पर अब्दुल्ला दिखाएँ</button></div><p>यह इस्लाम से पुराना है। पैग़ंबर मुहम्मद के पिता का नाम पहले से अब्दुल्ला था, और चूँकि बेटे के जन्म से पहले ही उनका देहांत हो गया, यह नाम इस्लाम-पूर्व अरब में ज़रूर चलता रहा होगा। नक्शे की प्रविष्टि एक हदीस भी दर्ज करती है जो ʿAbdullāh और ʿAbd al-Raḥmān को ख़ुदा के सबसे प्रिय नाम बताती है।</p><h3>एक नाम में व्याकरण का पाठ</h3><p>शब्द के बीच में देखिए। लिखित अरबी में <em>ʿabd</em> और <em>Allāh</em> दो शब्द हैं, तो Abdullah का <em>u</em> कहाँ से आया? व्याकरण से। शास्त्रीय अरबी वाक्य के कर्ता को <em>-u</em> अंत से चिह्नित करती है: <em>ʿabdu</em>। फिर <em>Allāh</em> का पहला <em>a</em> गिर जाता है, और <em>ʿabdu + Allāh</em> मिलकर <em>ʿAbdullāh</em> बन जाता है। रोज़मर्रा का यह नाम एक कारक-अंत बचाए हुए है जो बोलचाल की अरबी बहुत पहले खो चुकी है।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"12.0\" data-lng=\"8.5\" data-zoom=\"5\">🌍 उत्तरी नाइजीरिया पर जाएँ</button></div><h3>Abdullahi, Abdala, 阿卜杜拉</h3><p>फ़ारसी में वही स्वर <em>o</em> है, जिससे <strong>Abdollah</strong> बनता है। तुर्की, उर्दू, इंडोनेशियाई और मलय सब <strong>Abdullah</strong> लिखते हैं। मग़रिब में <strong>Abdallah</strong> और <strong>Abdellah</strong> हैं, उसी जगह दूसरे स्वर के साथ। बोस्नियाई एक <em>l</em> से <strong>Abdulah</strong> लिखते हैं।</p><p>नाम जितनी दूर जाता है, स्थानीय ध्वनियों के उतना क़रीब आता है। नाइजीरिया में यह आमतौर पर स्वर पर ख़त्म होता है, <strong>Abdullahi</strong>, जो हौसा में आम रूप है। स्वाहिली में <strong>Abdala</strong> है। चीनी में यह <strong>阿卜杜拉</strong> (Ābǔdùlā) लिखा जाता है, चार अक्षर सिर्फ़ ध्वनि के लिए।</p><h3>किसका बंदा?</h3><p>Allāh कई संभावित दूसरे हिस्सों में से एक है। <em>ʿAbd</em> के बाद अक्सर क़ुरआन में आए ख़ुदा के नामों में से कोई आता है, इसलिए <em>Abdul Rahman</em> है “रहमान का बंदा”। यहीं एक जाल है। <strong>Abdul</strong> का अर्थ है “... का बंदा”, यानी वाक्य अधूरा लटका रहता है। अरबी में लिखने पर यह अकेले पुरुष का नाम नहीं होता, हालाँकि अरबीभाषी समाजों के बाहर कभी-कभी पूरे नाम की तरह चलता है। भारत के 11वें राष्ट्रपति ए. पी. जे. अब्दुल कलाम के नाम के बीच में यही है।</p><p>यह सोच सिर्फ़ मुसलमानों की नहीं। हिब्रू में <strong>Obadiah</strong> और <strong>Abdiel</strong> में वही ढाँचा है, और यह अरबी नाम ख़ुद मिज़राही और सेफ़ार्दी यहूदियों में मिलता है, ख़ासकर इराक़ी और सीरियाई यहूदियों में।</p>","anthony-tony":"<p><strong>Antonius</strong> का अर्थ कोई नहीं जानता। यह एक रोमन परिवार का नाम था, शायद एट्रस्कन मूल का, तो शायद ऐसी भाषा से जिसने कम सुराग़ छोड़े। यह नाम रखने वालों में सबसे मशहूर सेनापति मार्कस एंटोनियस, यानी मार्क एंटनी थे, जिनका क्लियोपैट्रा के साथ अंत शेक्सपियर ने मंच पर उतारा।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setname\" data-name=\"anthony\">👤 नक्शे पर एंथनी दिखाएँ</button></div><p>एक मूर्तिपूजक पारिवारिक नाम दो संतों के रास्ते ईसाइयों तक पहुँचा। मिस्र के संन्यासी संत एंथनी महान को सभी भिक्षुओं का पिता कहा जाता है। 13वीं सदी के पादुआ के संत एंथनी ने मध्य युग में नाम को और मज़बूत किया।</p><h3>लैटिन परिवार</h3><p>ज़्यादातर भाषाओं ने लैटिन आकार थोड़े बदलाव से लिया। स्पेनिश और इतालवी <strong>Antonio</strong>, पुर्तगाली <strong>António</strong>, पोलिश <strong>Antoni</strong>, यूनानी <strong>Αντώνιος</strong>। कुछ ने अंत काट दिया: जर्मन, स्वीडिश, रोमानियाई और रूसी <strong>Anton</strong>, और बलाघात हर भाषा में अपनी मर्ज़ी से खिसकता है। फ़्रांसीसी <strong>Antoine</strong> /ɑ̃ˈtwan/ ने <em>-onius</em> को एक नए स्वर में मोड़ दिया, चेक ने बढ़ाकर <strong>Antonín</strong> किया, और हंगेरियाई ने अलग राह पकड़कर <strong>Antal</strong> बनाया, जहाँ <em>l</em> अनपेक्षित है।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"45.4\" data-lng=\"11.88\" data-zoom=\"6\">🌍 पादुआ पर जाएँ</button></div><h3>फूल से आया h</h3><p>अंग्रेज़ी अलग है। सदियों तक नाम में <em>h</em> नहीं था। फिर लोगों ने इसे यूनानी <em>anthos</em>, “फूल”, से जोड़ा, जो <em>chrysanthemum</em> और <em>anthology</em> की जड़ है। यह जुड़ाव ग़लत था, पर इसी के कारण 16वीं सदी में अंग्रेज़ी वर्तनी में <em>h</em> जुड़ गया। रोमन <em>Mark Antony</em> से तुलना करें, जिन्हें यह नहीं मिला।</p><p>नक्शा दिखाता है कि यह वर्तनी आज क्या कर रही है। ब्रिटिश खाने में /ˈæntəni/ है, सादे <em>t</em> के साथ, और अमेरिकी खाने में /ˈænθəni/, <em>thin</em> के <em>th</em> के साथ। दोनों खाने ठीक उसी ध्वनि में अलग हैं जिसे वह अतिरिक्त अक्षर दर्शाता है।</p><h3>Tony</h3><p>छोटे रूप में यह समस्या नहीं। <strong>Tony</strong> पहला शब्दांश छोड़ देता है और उसके साथ <em>th</em> का सवाल भी, और अपने दम पर मशहूर हुआ: टोनी बेनेट और टोनी हॉक इसी नाम के हैं। क्रोएशियाई में वही छोटा रूप Toni है, Ante और पूरे <strong>Antun</strong> के साथ।</p><p>यूरोप के बाहर यह नाम ईसाइयों के पास रहा। अरब ईसाई <strong>Anṭūn</strong> (أنطون) कहते हैं, कोरियाई कैथोलिक <strong>Antonio</strong>, और वियतनामी कैथोलिक <strong>Antôn</strong>, तो संत एंथनी के अनुयायी आज भी एक रोमन पारिवारिक नाम लिए चलते हैं जिसका अर्थ खो चुका है।</p>","catherine-kate-katya":"<p><strong>Catherine</strong> का मतलब कोई नहीं जानता। यूनानी नाम <strong>Aikaterínē</strong> (Αἰκατερίνη) है, और विक्शनरी उसके मूल को अनिश्चित बताती है। अक्सर कहा जाता है कि यह देवी हेकाटी से आया, हालाँकि <em>Oxford Dictionary of First Names</em> इसे असंतोषजनक मानती है। एक और सुझाव है <em>hekateros</em>, “दोनों में से हर एक”। कोई भी राय जीत नहीं पाई।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setname\" data-name=\"catherine\">👤 नक्शे पर कैथरीन दिखाएँ</button></div><h3>ग़लत अंदाज़े से आया h</h3><p>शुरुआती लोक व्युत्पत्ति ने जवाब का इंतज़ार नहीं किया। लोगों को इसमें यूनानी <em>katharos</em>, “शुद्ध”, सुनाई दिया, और वर्तनी पीछे चल पड़ी: मध्ययुगीन लैटिन में <em>Katerīna</em> के साथ <em>Catharīna</em> आ गया। तो Katharine का <em>h</em> और अंग्रेज़ी Catherine की “th” ध्वनि एक अंदाज़े से निकली है। फ़्रांसीसी <strong>Catherine</strong> में आज भी अक्षर है, ध्वनि नहीं। अंग्रेज़ी ने जो देखा वही बोला, और ग़लती सुनाई देने लगी।</p><p>नक्शा दिखाता है कि यह “सुधार” किसने लिया। जर्मन <strong>Katharina</strong> में <em>h</em> है। इतालवी <strong>Caterina</strong>, पुर्तगाली <strong>Catarina</strong>, स्वीडिश <strong>Katarina</strong> और रूसी <strong>Екатерина</strong> (Yekaterina) में नहीं। रूसी और रोमानियाई <em>Ecaterina</em> कुछ और बचाते हैं: यूनानी <em>Ai-</em> का शुरुआती स्वर, जो बाक़ी सबने छोड़ दिया।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"56.84\" data-lng=\"60.6\" data-zoom=\"4\">🌍 येकातेरिनबर्ग पर जाएँ</button></div><p>स्पेनिश ने अलग राह पकड़कर <strong>Catalina</strong> बनाया और हंगेरियाई ने <strong>Katalin</strong>, दोनों में <em>l</em> वहाँ है जहाँ बाक़ियों में <em>r</em>। पोलिश ने <strong>Katarzyna</strong> बनाया और फिर उसे सिकोड़कर <strong>Kasia</strong> कर दिया, जिसमें साझा ध्वनि मुश्किल से बची।</p><h3>पहिया और साम्राज्ञी</h3><p>नाम को शोहरत अलेक्ज़ान्ड्रिया की संत कैथरीन से मिली, जिन्हें ईसाई परंपरा के अनुसार पहिये पर तोड़े जाने की सज़ा मिली थी। उन्होंने छुआ तो पहिया टुकड़े-टुकड़े हो गया। इसीलिए घूमने वाली आतिशबाज़ी अंग्रेज़ी में <em>Catherine wheel</em> कहलाती है।</p><p>राजघरानों ने इसे ज़िंदा रखा। 18 नवंबर 1723 को बसा येकातेरिनबर्ग पीटर महान की पत्नी कैथरीन प्रथम के नाम पर है। ज़्यादा मशहूर साम्राज्ञी, कैथरीन महान, इस नाम के साथ पैदा ही नहीं हुई थीं। वे 1744 में जर्मन राजकुमारी सोफ़ी के रूप में रूस आईं, और उसी साल 28 जून को जब रूसी ऑर्थोडॉक्स चर्च ने उन्हें अपनाया, उन्होंने बपतिस्मा नाम येकातेरीना लिया, जिससे वे कैथरीन प्रथम की हमनाम बन गईं।</p><h3>Kasia, Katya, Karen</h3><p>छोटे रूपों की अपनी ज़िंदगी है। अंग्रेज़ी में Kate, Katie और Kitty हैं, रूसी में <strong>Katya</strong>, चेक में <strong>Katka</strong>। स्वीडिश <strong>Karin</strong> देती है और डेनिश <strong>Karen</strong>, जो 1940 के दशक में अंग्रेज़ी दुनिया में लोकप्रिय हुआ और 2017 से अपमानजनक अर्थ में ज़्यादा चलने लगा है। नक्शे के जापानी खाने में 花梨 Karin बस संयोग से वैसा सुनाई देता है: यह चीनी क्विंस के अक्षरों से लिखा जापानी नाम है।</p>","joseph-pepe":"<p><strong>José</strong> में <strong>Pepe</strong> जैसा कुछ नहीं दिखता, फिर भी हर स्पेनिश बोलने वाला जानता है कि दोनों एक ही आदमी हैं। यह उपनाम उस नाम का एक अजीब कोना है जो नक्शे के 25 खानों में फैला है, आयरिश <em>Seosamh</em> से कोरियाई <em>Yosep</em> तक।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setname\" data-name=\"joseph\">👤 नक्शे पर यूसुफ़ दिखाएँ</button></div><h3>एक अक्षर, तीन नियतियाँ</h3><p>नाम की शुरुआत हिब्रू <strong>Yosef</strong> (יוֹסֵף) से होती है, अर्थ “वह बढ़ाएगा”, मूल <em>yasaf</em> से। उत्पत्ति की पुस्तक में वह याकूब का ग्यारहवाँ बेटा है, जिसे भाई मिस्र में बेच देते हैं और जो अंत में फ़िरौन का सलाहकार बनता है। नया नियम मरियम के पति को भी यही नाम देता है।</p><p>यूनानी <em>Iōsḗph</em> और लैटिन <em>Ioseph</em> से होकर यह हर ईसाई भाषा में पहुँचा, और पहली ध्वनि अपने जाने-पहचाने तीन रास्तों पर चली गई। जर्मन /j/ रखती है: <strong>Josef</strong>। इतालवी उसे कड़ा करती है: <strong>Giuseppe</strong> /dʒuˈzɛppe/। पुर्तगाली नरम करती है: <strong>José</strong> /ʒuˈzɛ/, या सिर्फ़ Zé। स्पेनिश वही José लिखती है पर बोलती है /xoˈse/, गले के पीछे एक खरखराहट के साथ। आयरिश <strong>Seosamh</strong> निकलता है /ˈʃoːsəv/, जो न अपनी वर्तनी जैसा लगता है, न Joseph जैसा।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"40.4\" data-lng=\"-3.7\" data-zoom=\"5\">🌍 स्पेन पर जाएँ</button></div><p>इस्लाम एक समानांतर रूप लेकर चला। क़ुरआन के बारहवें अध्याय का नाम <strong>Yusuf</strong> है और वह मिस्र की कहानी सुनाता है, इसलिए अरबी Yūsuf, तुर्की Yusuf और फ़ारसी Yusof कभी यूनानी या लैटिन से गुज़रे ही नहीं। अरब ईसाई और मुसलमान यह नाम साझा करते हैं।</p><h3>P.P. की कहानी</h3><p>अब P की बात। जो व्याख्या सब दोहराते हैं वह एक संक्षेप है: संत यूसुफ़ <em>pater putativus</em> थे, यीशु के माने हुए पिता, चर्च के लेखन में इसे P.P. लिखा गया, और P.P. ज़ोर से पढ़ने पर <em>Pepe</em> बन गया। कहानी प्यारी है, और इसमें बाद में गढ़ी गई चीज़ की झलक है।</p><p>ज़्यादा संभावित रास्ता सीधी ध्वनि का है। स्पेनिश विकिपीडिया, मेक्सिकी अकादमी का हवाला देकर, इसका संभावित स्रोत पुराना रूप <em>Josepe</em> बताता है, जो <em>Josephus</em> से आया और वैसे ही छोटा हुआ जैसे इतालवी Giuseppe। नक्शा दिखाता है कि ऐसा कितना आम है। इतालवी में <strong>Beppe</strong> और <strong>Peppino</strong> हैं, चेक में <strong>Pepa</strong>, बवेरियाई जर्मन में <strong>Sepp</strong>। सब नाम का अगला हिस्सा फेंककर ज़ोरदार अक्षर <em>-sep-</em> रखते हैं। <em>-seppe</em> बन जाता है <em>Peppe</em>, और स्पेनिश <em>Pepe</em> इसी परिवार का है।</p><h3>Giuse, Yosep, Osip</h3><p>लैटिन लिपि पूर्वी छोर को भी समझाती है। कैथोलिक मिशनरियों ने वियतनाम में वियतनामी अक्षरों के हिसाब से लिखा <strong>Giuse</strong> छोड़ा और कोरिया में <strong>Yosep</strong> (요셉)। स्पेनिश ने फ़िलीपींस में <strong>Jose</strong> छोड़ा। रूसी में दो रूप एक साथ हैं: चर्च का <em>Iosif</em> और लोक रूप <em>Osip</em>, जो कवि मांडेलश्ताम का नाम था।</p>","margaret-pearl":"<p><strong>Margaret</strong> का अर्थ है “मोती”। लैटिन <em>Margarita</em> यूनानी <strong>margarítēs</strong> (μαργαρίτης) से आया, एक ऐसा शब्द जो ईरानी भाषाओं की ओर से यूनानी में आया और फ़ारसी <em>morvārīd</em> का रिश्तेदार है। यानी किसी यूनानी लड़की का नाम बनने से पहले ही यह परदेसी था।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setname\" data-name=\"margaret\">👤 नक्शे पर मार्गरेट दिखाएँ</button></div><h3>एक मोती, सोलह रूप</h3><p>इसे फैलाया संत मार्गरेट ने, जो चौथी सदी में अंताकिया में शहीद हुईं। बाद की किंवदंतियों में वे एक ड्रैगन से बच निकलती हैं, और मध्ययुगीन कला उन्हें उसके साथ दिखाती है। वे गर्भवती माँओं की संरक्षक बनीं, और चर्च जहाँ गया नाम वहाँ गया। नक्शे पर 16 रूप हैं।</p><p>ज़्यादातर ने लैटिन रूप रखा: स्पेनिश <strong>Margarita</strong>, जर्मन <strong>Margarete</strong>, स्वीडिश <strong>Margareta</strong>, रूसी <strong>Маргарита</strong>। कुछ ने उसे घिस दिया। चेक में <strong>Markéta</strong> है, हंगेरियाई में <strong>Margit</strong>। पोलिश <strong>Małgorzata</strong> अलग नाम लगता है जब तक व्यंजन क्रम से न पढ़ें: <em>m-ł-g-rz-t</em>, पहला <em>r</em> <em>ł</em> बन चुका है, और उसके दुलार वाले रूप <strong>Gosia</strong> में तो लगभग कुछ नहीं बचता।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"40.85\" data-lng=\"14.27\" data-zoom=\"6\">🌍 नेपल्स पर जाएँ</button></div><h3>फूल, कॉकटेल, पिज़्ज़ा</h3><p>फ़्रांसीसी <strong>Marguerite</strong> बग़ल की एक गली में मुड़ गया। यह शब्द डेज़ी का भी नाम है, और स्पेनिश <em>margarita</em> भी। स्पेनिश शब्द तब से आगे बढ़कर एक कॉकटेल तक पहुँच गया है।</p><p>इतालवी <strong>Margherita</strong> के पास पिज़्ज़ा है। एक लोकप्रिय किंवदंती कहती है कि 10 जून 1889 को नेपल्स के पिज़्ज़ा कारीगर राफ़ाएले एस्पोसितो ने नेपल्स आई हुई सावॉय की रानी मार्गेरीता के लिए तीन पिज़्ज़ा बनाए, और उन्हें इतालवी झंडे के रंगों वाला पसंद आया: टमाटर, मोत्ज़ारेला और तुलसी। यह किंवदंती के रूप में ही सुनाई जाती है; रानी को कौन-सा पसंद आया, यह जाँचा नहीं जा सकता; पिज़्ज़ा का नाम हर मेन्यू पर मिल जाता है।</p><h3>Greta, Rita और Peggy का P</h3><p>फिर आते हैं उपनाम, जो आगे या पीछे से टूटते हैं। पिछला हिस्सा रखें तो जर्मन और स्वीडिश <em>Margareta</em> से <strong>Greta</strong> मिलता है, अभिनेत्री ग्रेटा गार्बो का नाम, और इतालवी <em>Margherita</em> से <strong>Rita</strong>। कासिया की संत रीता (1381–1457) का जन्म का नाम Margherita Ferri Lotti था। जर्मन में Gretchen भी है। अगला हिस्सा रखें तो अंग्रेज़ी Meg और Maggie मिलते हैं।</p><p>और फिर <strong>Peggy</strong>। विक्शनरी इसे Maggie का बदला हुआ रूप बताती है और वहीं रुक जाती है: M से P कैसे बना, नहीं बताती। Daisy, फ़्रांसीसी जुड़ाव के बावजूद, अपना अलग शब्द है: पुरानी अंग्रेज़ी <em>dæġes ēage</em>, “दिन की आँख”।</p>","michael-question":"<p><strong>Michael</strong> एक सवाल है। हिब्रू <strong>Mikhaʼel</strong> (מִיכָאֵל) बना है <em>mi</em>, “कौन”, <em>ke</em>, “जैसा”, और <em>ʼel</em>, “ईश्वर” से: “ईश्वर जैसा कौन है?” अपेक्षित जवाब है “कोई नहीं”, तो Michael नाम का लड़का ज़िंदगी भर एक अलंकारिक सवाल लिए घूमता है।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setname\" data-name=\"michael\">👤 नक्शे पर मीकाईल दिखाएँ</button></div><p>इस नाम के स्वामी एक प्रधान स्वर्गदूत हैं, जिनका नाम दानिय्येल की पुस्तक (12:1) में है। बीज़ान्टिन सम्राटों ने यह नाम इतनी बार लिया कि माइकल नवम तक पहुँच गए।</p><h3>एक व्यंजन, छह जवाब</h3><p>नाम की असली दिलचस्प बात एक व्यंजन है। हिब्रू में स्कॉटिश <em>loch</em> के <em>ch</em> जैसी ध्वनि थी, और यूनानी <em>Michaḗl</em> ने उसे ची अक्षर से लिखा। नक्शे के 25 रूप दिखाते हैं कि हर भाषा ने उस ध्वनि का क्या किया जो शायद उसके पास थी ही नहीं।</p><p>इतालवी <strong>Michele</strong> /miˈkɛːle/ ने उसे सादा <em>k</em> बना दिया। फ़्रांसीसी <strong>Michel</strong> /miʃɛl/ ने <em>sh</em> बनाया। स्पेनिश <strong>Miguel</strong> /miˈɣel/ ने उसे घोष ध्वनि बना दिया। रोमानियाई <strong>Mihai</strong> /miˈhaj/ और हंगेरियाई <strong>Mihály</strong> /ˈmihaːj/ ने उसे कमज़ोर करके <em>h</em> कर दिया। रूसी <strong>Михаил</strong> /mʲɪxɐˈil/ ने मूल खरखराहट रखी। अंग्रेज़ी <em>ch</em> लिखती है, <em>k</em> बोलती है, और पहले स्वर को mine का <em>i</em> बना देती है: /ˈmaɪkəl/, हिब्रू से कोसों दूर।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"41.0\" data-lng=\"28.97\" data-zoom=\"5\">🌍 कॉन्स्टेंटिनोपल पर जाएँ</button></div><p>नाम का अंत भी घिस गया। हिब्रू <em>ʼel</em>, “ईश्वर”, आर्मेनियाई <strong>Mikayel</strong> में सलामत है, जबकि रोमानियाई Mihai ने <em>l</em> पूरी तरह खो दिया, तो वाक्य का “ईश्वर” चला गया। पोलिश <strong>Michał</strong> उसे अंतिम <em>ł</em> के रूप में रखता है।</p><h3>Mīkāʼīl और Mīkhāʼīl</h3><p>अरबी में भी यह फ़रिश्ता है, क़ुरआनी रूपों <strong>Mīkāʼīl</strong> और Mīkāl में, और तुर्की <strong>Mikail</strong> तथा फ़ारसी Mikaʼil उसी का अनुसरण करते हैं। अरब ईसाई इसकी जगह <em>Mīkhāʼīl</em> लिखते हैं, खरखराहट लौटाकर। इथियोपिया में अम्हारिक रूप <strong>Mikaʼel</strong> है, हिब्रू के क़रीब।</p><p>प्यार के नाम इस सवाल को छोटा करते जाते हैं। अंग्रेज़ी में Mike, रूसी में <strong>Misha</strong>, जर्मन में Michi, यूनानी में Michalis। फ़्रांसीसी स्त्रीलिंग <strong>Michelle</strong> को 1965 में बीटल्स का एक गाना मिला। गाने वालों में से किसी ने नहीं पूछा कि ईश्वर जैसा कौन है।</p>","moses-musa":"<p>बाइबल अपनी व्युत्पत्ति ख़ुद देती है। निर्गमन 2:10 में फ़िरौन की बेटी बच्चे का नाम मूसा रखती है क्योंकि उसने उसे पानी से निकाला था। हिब्रू में यह ठीक बैठता है: <strong>Mosheh</strong> (מֹשֶׁה) क्रिया <em>masha</em>, “निकालना”, जैसा सुनाई देता है। विद्वान इसे लोक व्युत्पत्ति मानते हैं।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setname\" data-name=\"moses\">👤 नक्शे पर मूसा दिखाएँ</button></div><h3>एक मिस्री अंत</h3><p>पाठकों ने दो दिक़्क़तें बहुत पहले देख लीं। मिस्र की राजकुमारी को हिब्रू कैसे आती? इसने अब्राहम इब्न एज़्रा जैसे मध्ययुगीन टीकाकारों को उलझाया। और 11वीं सदी के विद्वान इसहाक बेन आशेर हलेवी ने ध्यान दिलाया कि <em>mōše</em> कर्तृवाच्य रूप है, “निकालने वाला”, कर्मवाच्य “निकाला हुआ” नहीं। मिस्री धातु <em>msy</em>, “की संतान”, या <em>mose</em>, इसके बदले संभावित स्रोत मानी गई है।</p><p>यह मिस्री नामों का बहुत साधारण अंत है। Thutmose का अर्थ है “थोथ से जन्मा”, Ramose “रा से जन्मा”। सिर्फ़ Mose कहलाने वाले व्यक्ति का नाम ऐसा होगा जिसमें से देवता का नाम हट गया हो। अगर यह सही है, तो हिब्रू विधिदाता ने आधा मिस्री नाम लेकर जीवन बिताया, और निर्गमन की कहानी उसे हिब्रू में समझाकर निकल गई।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"26\" data-lng=\"32\" data-zoom=\"5\">🌍 नील नदी पर जाएँ</button></div><h3>दो धाराएँ</h3><p>फिर नाम दो बड़ी धाराओं में चला। यूनानी ने बीच में एक अतिरिक्त स्वर के साथ <em>Mōÿsês</em> लिखा, और वह स्वर ईसाई यूरोप में आज भी सुनाई देता है। फ़्रांसीसी <strong>Moïse</strong> /mɔiz/ को उसे अलग रखने के लिए दो बिंदु चाहिए। स्पेनिश और पुर्तगाली में <strong>Moisés</strong> है, रूसी में <strong>Моисей</strong> (Moisey), पोलिश में <strong>Mojżesz</strong>, आधुनिक यूनानी में <strong>Μωυσής</strong> (Moysís)। अंग्रेज़ी और जर्मन <strong>Moses</strong> ने वह स्वर फिर खो दिया और यूनानी अंत <em>-s</em> रखा, और इतालवी <strong>Mosè</strong> ने दोनों नहीं रखे। आर्मेनियाई में <strong>Movses</strong> है, जहाँ यूनानी स्वर की जगह <em>v</em> है।</p><h3>Mūsā</h3><p>दूसरी धारा क़ुरआन है, जहाँ उनका नाम किसी भी और पैग़ंबर से ज़्यादा आता है। अरबी <strong>Mūsā</strong> (موسى) ऐसा आम नाम है जिसमें यूनानी का कोई असर नहीं, और यह नक्शे पर पश्चिम अफ़्रीका से चीन तक फैला है: तुर्की, इंडोनेशियाई, हौसा और स्वाहिली <strong>Musa</strong>, फ़ारसी और उर्दू Musā, हिंदी <strong>मूसा</strong>, बांग्ला <strong>মূসা</strong>, और चीन के हुई मुसलमानों में <strong>穆萨</strong> (Mùsà)। 30 खानों में से क़रीब एक तिहाई यही रूप हैं। अम्हारिक <strong>Muse</strong> (ሙሴ) दोनों के बीच है।</p><p>हिब्रू ख़ुद /moˈʃe/ बोलती है, <em>sh</em> के साथ। जॉर्जियाई <strong>Mose</strong> और कोरियाई <strong>Mose</strong> (모세) में सादा <em>s</em> है, और संयोग से वे मिस्री <em>mose</em> के बहुत पास आ उतरते हैं, जहाँ से शायद यह सब शुरू हुआ।</p>","noah-nuh":"<p><strong>Noah</strong> नक्शे के सबसे छोटे नामों में से एक है और सबसे ज़्यादा फैले नामों में से भी। हिब्रू <strong>Noaḥ</strong> (נֹחַ) का अर्थ है “विश्राम, चैन”, धातु <em>nuaḥ</em> से, और यह प्रविष्टि 38 खाने भरती है। उत्पत्ति 5:29 नाम को थोड़े अलग विचार से जोड़ती है: यह बच्चा हमारी मेहनत और कष्ट में हमें दिलासा देगा। इसकी हिब्रू धातु की दो व्याख्याएँ हैं: <em>nuach</em>, “विश्राम”, जो ज़्यादा संभावित है, और “दिलासा देना” वाली एक धातु जिसका अंतिम व्यंजन गिर गया।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setname\" data-name=\"noah\">👤 नक्शे पर नूह दिखाएँ</button></div><h3>ग़ायब होता ḥ</h3><p>सारी दिलचस्प बात अंत में होती है। हिब्रू रूप <em>ḥ</em> पर ख़त्म होता है, गले की एक खुरदरी ध्वनि, आज /ˈno.aχ/। यूनानी में ग्रसनी व्यंजन नहीं था, और <em>Nôe</em> सीधे स्वर पर रुक गया। लैटिन <em>Noe</em> ने नक़ल की, और रोमांस भाषाएँ पीछे चलीं: फ़्रांसीसी और स्पेनिश <strong>Noé</strong>, इतालवी <strong>Noè</strong>, रोमानियाई Noe। पोलिश और चेक Noe, यूनानी Νώε, जॉर्जियाई Noe और वियतनामी <strong>Nôê</strong> इसी धारा से निकले।</p><p>रूसी <strong>Ной</strong> (Noy), यूक्रेनी Ной और आर्मेनियाई <strong>Նոյ</strong> (Noy) अंत को <em>y</em> से बंद करते हैं, तो नाम एक अक्षर का हो जाता है। जर्मन और डच अंग्रेज़ी जैसा दिखने वाला <strong>Noah</strong> लिखते हैं, और फ़िनिश तथा क्रोएशियाई में सादा Noa है।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"39.7\" data-lng=\"44.3\" data-zoom=\"5\">🌍 अरारात पर्वत पर जाएँ</button></div><p>अंग्रेज़ी ने अक्षर रखा और ध्वनि छोड़ दी। किंग जेम्स बाइबल का <em>Noah</em> हिब्रू वर्तनी का अनुसरण करता है, फिर भी <em>h</em> कोई नहीं बोलता: यह /ˈnoʊə/ है, और अंतिम व्यंजन सिर्फ़ काग़ज़ पर बचा है। स्वीडिश <strong>Noak</strong> और भी अजीब है, अंत में असली <em>k</em> के साथ।</p><h3>इस्लामी धारा में बचा</h3><p>इस्लामी धारा ने इसे कभी नहीं खोया। क़ुरआन में Nūḥ नाम का पूरा अध्याय है, और अरबी <strong>Nūḥ</strong> (نوح) /nuːħ/ अपनी कंठ ध्वनि पर ख़त्म होता है, जो हिब्रू के सबसे क़रीब है। आगे जाकर ध्वनि नरम होती है: फ़ारसी /nuːh/, तुर्की, इंडोनेशियाई और मलय <strong>Nuh</strong> हल्के <em>h</em> के साथ। हौसा और स्वाहिली <strong>Nuhu</strong> एक स्वर जोड़ते हैं ताकि शब्द उनके ढंग से ख़त्म हो। चीन के हुई मुसलमान <strong>努哈</strong> (Nǔhā) लिखते हैं, और अम्हारिक <strong>Noḥ</strong> (ኖኅ) में इस ध्वनि का अपना अक्षर है।</p><h3>फिर चलन में</h3><p>नाम का दूसरा जीवन हाल का है। 2010 और 2020 के दशकों में Noah अर्जेंटीना और ऑस्ट्रेलिया से लेकर जर्मनी, स्वीडन, फ़िलीपींस और अमेरिका तक के देशों में नवजात लड़कों के सबसे लोकप्रिय नामों में रहा है।</p><p>यह बाइबल से बाहर भी फैला है। क्रोएशिया में <strong>Noa</strong> है, और जापान में <strong>ノア</strong>, जो 乃亜 जैसे अक्षरों से लिखा जाता है। अब इसमें उस अंतिम व्यंजन की कोई ज़रूरत नहीं बची।</p>","peter-rock":"<p>पतरस मूल रूप से एक उपनाम था। उस मछुआरे का असली नाम शमौन था। यूहन्ना के सुसमाचार में यीशु उससे कहते हैं कि वह <strong>कैफा</strong> कहलाएगा, और पाठ बताता है कि इसका अर्थ “पत्थर” है (यूहन्ना 1:42)। कैफा अरामी <em>Kēfā</em> का यूनानी लिपि वाला रूप है। यूनानी ने इसका अनुवाद भी किया: <strong>Pétros</strong> (Πέτρος), और यही अनुवाद आज नक्शे के 29 खानों में फैला है। बाइबल के ज़्यादातर नाम ध्वनि के सहारे दूसरी भाषाओं में गए; यह नाम अर्थ के सहारे गया।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setname\" data-name=\"peter\">👤 नक्शे पर पतरस दिखाएँ</button></div><h3>वह श्लेष जिसे यूनानी चाहिए</h3><p>नए नियम में दोनों रूप बचे हैं। पौलुस अधिकतर कैफा लिखते हैं (गलातियों 2:9 में याकूब, कैफा और यूहन्ना के नाम हैं), जबकि सुसमाचार पतरस लिखते हैं। अनूदित नाम और बिना अनुवाद का नाम एक ही पुस्तक में साथ-साथ खड़े हैं।</p><p>अनुवाद से एक श्लेष संभव हुआ। मत्ती 16:18 में यीशु कहते हैं कि वह पतरस है और इसी चट्टान पर वे अपनी कलीसिया बनाएँगे। यूनानी में ये दो शब्द <em>Pétros</em> और <em>pétra</em> हैं, इसलिए सुनने वाला तुरंत पकड़ लेता है; हिंदी या अंग्रेज़ी में “पतरस” और “चट्टान” का कोई नाता नहीं। फ़्रांसीसी में यह पूरा बचा है: <em>tu es Pierre, et que sur cette pierre</em>, क्योंकि व्यक्ति <em>Pierre</em> और पत्थर <em>pierre</em> एक ही शब्द हैं। स्पेनिश में भी <em>Pedro</em> के साथ <em>piedra</em> है, पर 1960 का रेना-वालेरा अनुवाद <em>roca</em> लिखता है।</p><h3>एक लैटिन शब्द, तीन ध्वनि-नियम</h3><p>लैटिन <strong>Petrus</strong> फिर हर रोमांस भाषा के सामान्य ध्वनि-परिवर्तनों से गुज़रा। फ़्रांसीसी ने <em>r</em> से पहले का <em>t</em> खो दिया, ठीक वैसे जैसे <em>pater</em> से <em>père</em> बना। स्पेनिश और पुर्तगाली ने उसे नरम करके <strong>Pedro</strong> बनाया। इतालवी ने उसे रखा और स्वर तोड़ा: <strong>Pietro</strong>। दूर पूर्व की रोमानियाई <strong>Petru</strong> के साथ लैटिन के सबसे पास रही। यह किसी ने तय नहीं किया; नाम बस बाक़ी शब्दों की तरह बदला।</p><h3>उत्तर और पूर्व</h3><p>उत्तर की ओर नाम छोटा होता गया। स्वीडिश में Petter और Per, नॉर्वेजियाई में Peder, डच में Pieter और रोज़मर्रा का Piet, फ़िनिश में Petteri और Pekka हैं। स्लाव रूप लैटिन के ज़्यादा पास हैं: पोलिश <strong>Piotr</strong>, चेक Petr, यूक्रेनी Petro और रूसी <strong>Пётр</strong> (Pyotr), घर में Petya। ज़ार पीटर महान ने 27 मई 1703 को अपना नया शहर बसाया और उसका नाम अपने नहीं, प्रेरित के नाम पर रखा, यानी सेंट पीटर्सबर्ग भी “पत्थर” नाम का शहर है।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"59.94\" data-lng=\"30.31\" data-zoom=\"5\">🌍 सेंट पीटर्सबर्ग पर जाएँ</button></div><h3>p नहीं, तो दूसरा रास्ता</h3><p>जिन भाषाओं में ज़रूरी ध्वनियाँ नहीं थीं, उन्होंने नाम को फिर से गढ़ा। अरबी में <em>p</em> नहीं है, इसलिए अरब जगत के ईसाई <strong>Buṭrus</strong> (بطرس) कहते हैं, और यूनानी अंत <em>-os</em> यहाँ <em>-us</em> बनकर बचा है। अम्हारिक <strong>Ṗeṭros</strong> (ጴጥሮስ) दोनों व्यंजनों को इजेक्टिव अक्षरों से लिखती है। कोरियाई कैथोलिक <strong>Bedeuro</strong> (베드로) कहते हैं, जहाँ एक स्वर उस <em>tr</em> को तोड़ता है जिसकी कोरियाई में अनुमति नहीं, और वियतनामी कैथोलिक <strong>Phêrô</strong> कहते हैं।</p><p>स्त्री नाम Petra से चक्र पूरा होता है। यह पुरुष नाम से बना है, पर वर्तनी में यूनानी संज्ञा <em>pétra</em> “चट्टान” जैसा ही है, यानी मत्ती के श्लेष का दूसरा आधा हिस्सा।</p>","sophia-wisdom":"<p><strong>Sophia</strong> एक जातिवाचक संज्ञा है। यूनानी <strong>sophía</strong> (σοφία) का अर्थ है “प्रज्ञा”, वही शब्द जो <em>philosophía</em>, “प्रज्ञा का प्रेम”, के भीतर बैठा है। यूहन्ना या पतरस के विपरीत इसे किसी व्यक्ति तक खोजने की ज़रूरत नहीं: लड़की का नाम Sophia रखना उसे प्रज्ञा नाम देना है, जैसे कृपा या आशा नाम देना।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"setname\" data-name=\"sophia\">👤 नक्शे पर सोफ़िया दिखाएँ</button></div><h3>प्रज्ञा और उसकी बेटियाँ</h3><p>संतों के कैलेंडर में भी एक सोफ़िया है, दूसरी सदी की शहीद, जिनकी तीन बेटियाँ थीं: विश्वास, आशा और प्रेम। प्रज्ञा और उसके बच्चे, जो सब सद्गुण हैं, परिवार से ज़्यादा प्रवचन जैसे लगते हैं। कॉन्स्टेंटिनोपल का महान गिरजाघर हागिया सोफ़िया “पवित्र प्रज्ञा” के नाम पर है, यानी ख़ुद प्रज्ञा, कोई स्त्री नहीं।</p><h3>महल से महल तक</h3><p>फिर नाम राजघरानों से होकर चला। मध्य युग में यूरोपीय महाद्वीप के राजपरिवारों में यह आम था, और जर्मन हैनोवर वंश इसे 18वीं सदी में ब्रिटेन लाया। हेनरी फ़ील्डिंग ने इसे <em>टॉम जोन्स</em> (1749) में इस्तेमाल किया। सोफ़ी नाम की एक जर्मन राजकुमारी 1744 में रूस पहुँची और साम्राज्ञी कैथरीन महान बनी।</p><div class=\"trivia-actions\"><button type=\"button\" class=\"trivia-action\" data-action=\"panto\" data-lat=\"41.01\" data-lng=\"28.98\" data-zoom=\"6\">🌍 हागिया सोफ़िया पर जाएँ</button></div><h3>S, Z, Ž, Zs</h3><p>यूनानी अक्षर <em>phi</em> और शुरुआती <em>s</em> नक्शे के 21 रूपों की विविधता तय करते हैं। पश्चिमी भाषाओं ने <em>f</em> ध्वनि रखी, <em>ph</em> या <em>f</em> लिखकर: फ़्रांसीसी और जर्मन <strong>Sophie</strong>, स्पेनिश <strong>Sofía</strong>, इतालवी और स्वीडिश <strong>Sofia</strong>। जॉर्जियाई, जिसमें <em>f</em> नहीं है, कहती है <strong>Sopio</strong> (სოფიო)।</p><p>मध्य यूरोप ने शुरुआत बदली। पोलिश <strong>Zofia</strong>, चेक <strong>Žofie</strong> और हंगेरियाई <strong>Zsófia</strong> ने <em>s</em> की जगह घोष व्यंजन रखा, तो तीन पड़ोसी एक ही पहला अक्षर तीन तरह लिखते हैं। पोलिश में प्यार का नाम <strong>Zosia</strong> है, हंगेरियाई में Zsófi।</p><p>रूसी <strong>София</strong> ने एक ऐसा दुलार रूप दिया जो घर छोड़ गया। <strong>Sonya</strong> रूसी लघु रूप है, और उपन्यासों ने इसे अंग्रेज़ी में फैलाया: दोस्तोयेव्स्की का <em>अपराध और दंड</em> (1866) और तोल्स्तोय का <em>युद्ध और शांति</em> (1869)।</p><p>एक फ़िल्म सितारा उल्टी यात्रा दिखाती है। Sofia नाम से जन्मी इतालवी अभिनेत्री ने पर्दे के लिए यूनानी दिखने वाली वर्तनी चुनी, और Sophia Loren बनी। तो पुराना <em>ph</em> ग्लैमर के लिए लौटा, और यूनानियों की प्रज्ञा पोस्टरों पर चढ़ गई।</p>"};
